fn generate_rand_url(pattern: &str) -> String {
    // very simplistic: replace [a-z] with random lower, [0-9] with digit, * etc
    // For testing, we just replace bracket expr with random
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut out = String::new();
    let mut chars = pattern.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '[' {
            let mut inner = String::new();
            while let Some(ch) = chars.next() {
                if ch == ']' { break; }
                inner.push(ch);
            }
            // inner like a-z or 0-9 or a-z etc
            // choose random char from range if contains -
            if inner.contains('-') {
                // split by ?
                let parts: Vec<&str> = inner.split('-').collect();
                if parts.len() >=2 {
                    let start = parts[0].chars().last().unwrap_or('a');
                    let end = parts[1].chars().next().unwrap_or('z');
                    if start <= end {
                        let s = start as u8;
                        let e = end as u8;
                        let r = rng.gen_range(s..=e) as char;
                        out.push(r);
                        continue;
                    }
                }
            }
            // else random from inner chars
            if !inner.is_empty() {
                let idx = rng.gen_range(0..inner.len());
                out.push(inner.chars().nth(idx).unwrap());
            } else {
                out.push('a');
            }
        } else if c == '*' || c == '+' || c == '?' {
            // ignore for simplicity
            out.push(c);
        } else {
            out.push(c);
        }
    }
    out
}
