    }

    // Perform actual socket connect
    use std::net::TcpStream;
    use std::io::{Read, Write};
    use std::time::Duration;
    let connect_timeout = parse_duration(matches.get_one::<String>("connect-timeout").map(|s| s.as_str()).unwrap_or("5s")).unwrap_or(Duration::from_secs(5));
    let timeout = matches.get_one::<String>("timeout").map(|s| parse_duration(s).unwrap_or(Duration::from_secs(0))).unwrap_or(Duration::from_secs(0));
    // connect-to handling
    let mut target_host = host.clone();
    let mut target_port = port;
    if let Some(connect_tos) = matches.get_many::<String>("connect-to") {
        for ct in connect_tos {
            // format: example.org:443:localhost:8443
            // parse as host:port:target_host:target_port
            let parts: Vec<&str> = ct.split(':').collect();
            if parts.len() == 4 {
                let orig_host = parts[0];
                let orig_port = parts[1].parse::<u16>().unwrap_or(0);
                let tgt_host = parts[2];
                let tgt_port = parts[3].parse::<u16>().unwrap_or(0);
                if orig_host == host && orig_port == port {
                    target_host = tgt_host.to_string();
                    target_port = tgt_port;
                }
            }
        }
    }

    // ipv4/ipv6? ignore

    let addr = format!("{}:{}", target_host, target_port);
    let mut stream = match TcpStream::connect_timeout(&addr.parse().unwrap_or(std::net::SocketAddr::from(([127,0,0,1], target_port))), connect_timeout) {
        Ok(s) => s,
        Err(e) => {
            // try resolve? Use std ToSocketAddrs
            // For simplicity, attempt second method
            let addrs = format!("{}:{}", target_host, target_port).to_socket_addrs();
            match addrs {
                Ok(mut iter) => {
                    if let Some(sock_addr) = iter.next() {
                        match TcpStream::connect_timeout(&sock_addr, connect_timeout) {
                            Ok(s) => s,
                            Err(e2) => return Err(format!("{}", e2)),
                        }
                    } else {
                        return Err(format!("{}", e));
                    }
                },
                Err(e2) => return Err(format!("{}", e2)),
            }
        }
    };
    // set timeouts
    if timeout != Duration::from_secs(0) {
        stream.set_read_timeout(Some(timeout)).ok();
        stream.set_write_timeout(Some(timeout)).ok();
    }

    // Build HTTP request string
    let mut request_str = format!("{} {} {}\r\n", method_for_debug, query, version_display);
    for (k,v) in &display_headers {
        request_str.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = &body {
        request_str.push_str(&format!("content-length: {}\r\n", b.len()));
    }
    request_str.push_str("\r\n");
    // send
    if let Err(e) = stream.write_all(request_str.as_bytes()) {
        return Err(format!("{}", e));
    }
    if let Some(b) = &body {
        if let Err(e) = stream.write_all(b) {
            return Err(format!("{}", e));
        }
    }

    // read response
    let mut resp_buf = Vec::new();
    let mut tmp = [0u8; 4096];
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => resp_buf.extend_from_slice(&tmp[..n]),
            Err(e) => {
                if e.kind() == std::io::ErrorKind::WouldBlock || e.kind() == std::io::ErrorKind::TimedOut {
                    return Err("timeout".to_string());
                }
                return Err(format!("{}", e));
            }
        }
    }
    // parse response for debug output? Need to extract status, version, headers, body
    let resp_str = String::from_utf8_lossy(&resp_buf);
    let mut lines = resp_str.lines();
    let status_line = lines.next().unwrap_or("");
    let mut status_code = 200;
    let mut version_resp = "HTTP/1.1";
    if status_line.starts_with("HTTP/") {
        let parts: Vec<&str> = status_line.split_whitespace().collect();
        if parts.len() >=2 {
            version_resp = parts[0];
            status_code = parts[1].parse().unwrap_or(200);
        }
    }
    let mut resp_headers: std::collections::BTreeMap<String,String> = std::collections::BTreeMap::new();
    let mut body_start = 0;
    for (i, line) in resp_str.split("\r\n").enumerate() {
        if i==0 { continue; }
        if line.is_empty() {
            // find double CRLF position
            if let Some(pos) = resp_str.find("\r\n\r\n") {
                body_start = pos+4;
            }
            break;
        }
        if let Some((k,v)) = line.split_once(':') {
            resp_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
        }
    }
    let body_bytes = if body_start < resp_buf.len() { &resp_buf[body_start..] } else { b"" };

    // print response similar to original
    println!("\nResponse {{");
    println!("    status: {},", status_code);
    println!("    version: {},", version_resp);
    println!("    headers: {{");
    for (k,v) in &resp_headers {
        println!("        \"{}\": \"{}\",", k, v);
    }
    println!("    }},");
    println!("    body: b\"{}\",", String::from_utf8_lossy(body_bytes).replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r"));
    println!("}}");

    Ok(())
}

fn parse_duration(s: &str) -> Result<std::time::Duration, String> {
    // Very simplified parser to handle ns, us, ms, s, m, h etc
    // Original errors: "expected number at 0" if not starting with number, and "unknown time unit"
    let s = s.trim();
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }
    // find where number ends
    let mut num_end = 0;
    let mut has_dot = false;
    for (i,c) in s.char_indices() {
        if c.is_ascii_digit() || c=='.' {
            if c=='.' {
                if has_dot { break; }
                has_dot=true;
            }
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if num_end==0 {
        return Err("expected number at 0".to_string());
    }
    let num_str = &s[..num_end];
    let unit_str = s[num_end..].trim();
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let mult = match unit_str {
        "" => 1.0,
        "ns" => 1e-9,
        "us" | "µs" | "μs" => 1e-6,
        "ms" => 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => 1.0,
        "m" | "min" | "mins" | "minute" | "minutes" => 60.0,
        "h" | "hour" | "hours" => 3600.0,
        "d" | "day" | "days" => 86400.0,
        "w" | "week" | "weeks" => 604800.0,
        _ => {
            return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit_str));
        }
    };
    let secs = num * mult;
    Ok(std::time::Duration::from_secs_f64(secs))
}

