fn generate_simple_rand_url(pattern: &str) -> String {
    // Simplified: handle [a-z], [A-Z], [0-9], [a-z0-9], etc and ignore ., handle * with max-repeat
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut out = String::new();
    let mut chars = pattern.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '[' {
            let mut inner = String::new();
            while let Some(ch) = chars.next() {
                if ch == ']' { break; }
                inner.push(ch);
            }
            // parse inner: could be like a-z, A-Z, 0-9, a-zA-Z0-9 etc, or a set like abc
            let mut candidates: Vec<char> = Vec::new();
            let mut inner_chars = inner.chars().peekable();
            while let Some(ch) = inner_chars.next() {
                if let Some(&'-') = inner_chars.peek() {
                    // range
                    inner_chars.next(); // consume -
                    if let Some(end) = inner_chars.next() {
                        let start = ch;
                        if start <= end {
                            for rc in (start as u8)..=(end as u8) {
                                candidates.push(rc as char);
                            }
                        }
                    }
                } else {
                    candidates.push(ch);
                }
            }
            if !candidates.is_empty() {
                let idx = rng.gen_range(0..candidates.len());
                out.push(candidates[idx]);
            } else {
                out.push('a');
            }
            // handle following quantifiers * + ? {m,n} – we ignore for now and maybe repeat
            // peek next char for *, +, ?, {
            if let Some(&next) = chars.peek() {
                if next == '*' || next == '+' {
                    chars.next();
                    // random repeat up to max-repeat default 4
                    let max_rep = 4;
                    let repeat = rng.gen_range(0..=max_rep);
                    let last = out.pop().unwrap_or('a');
                    for _ in 0..repeat {
                        out.push(last);
                    }
                    out.push(last);
                } else if next == '{' {
                    // parse {n} or {n,} or {n,m}
                    let mut brace = String::new();
                    chars.next(); // consume {
                    while let Some(ch) = chars.next() {
                        if ch == '}' { break; }
                        brace.push(ch);
                    }
                    // ignore, treat as one
                }
            }
        } else {
            out.push(c);
        }
    }
    out
}

fn do_debug_request(matches: &clap::ArgMatches, url_str: &str) -> Result<(), String> {
    // Build request using std net
    // Parse URL
    let parsed = match url::Url::parse(url_str) {
        Ok(u) => u,
        Err(e) => return Err(format!("invalid url: {}", e)),
    };
    let host = parsed.host_str().ok_or("no host")?.to_string();
    let port = parsed.port_or_known_default().unwrap_or(80);
    let path = if parsed.path().is_empty() { "/" } else { parsed.path() };
    let query = if let Some(q) = parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };
    let method = matches.get_one::<String>("method").map(|s| s.as_str()).unwrap_or("GET");
    // headers
    let mut headers_vec: Vec<(String,String)> = Vec::new();
    if let Some(hs) = matches.get_many::<String>("headers") {
        for h in hs {
            if let Some((k,v)) = h.split_once(':') {
                headers_vec.push((k.trim().to_string(), v.trim().to_string()));
            }
        }
    }
    // accept
    if let Some(a) = matches.get_one::<String>("accept") {
        headers_vec.push(("accept".to_string(), a.clone()));
    }
    // content-type
    if let Some(ct) = matches.get_one::<String>("content-type") {
        headers_vec.push(("content-type".to_string(), ct.clone()));
    }
    // host header
    if let Some(h) = matches.get_one::<String>("host") {
        headers_vec.push(("host".to_string(), h.clone()));
    } else {
        headers_vec.push(("host".to_string(), format!("{}:{}", host, port)));
        // Actually original host header for non-default port includes port? In earlier debug, host was "127.0.0.1:18991"
        // So use host:port if port not default? For now include port.
    }
    // basic auth
    if let Some(auth) = matches.get_one::<String>("basic-auth") {
        if auth.contains(':') {
