    }
    if !has_user_agent {
        display_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string());
    }
    for (k,v) in headers_vec.iter() {
        display_headers.insert(k.to_lowercase(), v.clone());
    }

    // Now create the Request debug string
    // The original format:
    // Request {
    //     method: GET,
    //     uri: /,
    //     version: HTTP/1.1,
    //     headers: {
    //         "accept": "*/*",
    //         ...
    //     },
    //     body: Full {
    //         data: None,
    //     },
    // }

    println!("Request {{");
    println!("    method: {},", method_for_debug);
    println!("    uri: {},", uri_display);
    println!("    version: {},", version_display);
    println!("    headers: {{");
    for (k,v) in &display_headers {
        println!("        \"{}\": \"{}\",", k, v);
