    println!("    }},");
    println!("    body: Full {{");
    if let Some(b) = &body {
        // display as b"..."
        // need to escape? original shows b"file body content\n" or b"hello body" etc
        // Use debug format for byte string? We'll try to show as b"..." with escaping.
        // For simplicity, if body is utf8, show as string, else debug.
