            let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if p==0.10 { "10" } else if p==0.25 { "25" } else if p==0.50 { "50" } else if p==0.75 { "75" } else if p==0.90 { "90" } else if p==0.95 { "95" } else if p==0.99 { "99" } else { "" });
            let val = if durations.is_empty() {
                None
            } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                Some(durations[idx])
            };
            latency_percentiles.insert(key, val);
        }

        // rps calculation: we will compute based on request end times sorted
        let mut end_times: Vec<f64> = results_vec.iter().map(|r| r.end).collect();
        end_times.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut rps_values: Vec<f64> = Vec::new();
        if end_times.len()>1 {
            for i in 1..end_times.len() {
                let delta = end_times[i] - end_times[i-1];
                if delta>0.0 {
                    rps_values.push(1.0/delta);
                }
            }
        }
        if rps_values.is_empty() && !end_times.is_empty() {
            // if only one request, rps = 1/total? or requestsPerSec? We'll use requestsPerSec
            rps_values.push(requests_per_sec);
        }
        rps_values.sort_by(|a,b| a.partial_cmp(b).unwrap());

        let rps_mean = if !rps_values.is_empty() { rps_values.iter().sum::<f64>()/rps_values.len() as f64 } else { f64::NAN };
        let rps_max = rps_values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let rps_min = rps_values.iter().cloned().fold(f64::INFINITY, f64::min);
        let rps_stddev = if rps_values.len()>1 {
            let mean = rps_mean;
            let var = rps_values.iter().map(|v| (v-mean)*(v-mean)).sum::<f64>()/rps_values.len() as f64;
            Some(var.sqrt())
        } else {
            None
        };
        let mut rps_percentiles: BTreeMap<String, Option<f64>> = BTreeMap::new();
        for &p in &percentiles {
            let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if p==0.10 { "10" } else if p==0.25 { "25" } else if p==0.50 { "50" } else if p==0.75 { "75" } else if p==0.90 { "90" } else if p==0.95 { "95" } else if p==0.99 { "99" } else { "" });
            let val = if rps_values.is_empty() {
                None
            } else {
                let idx = ((p * rps_values.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, rps_values.len()-1);
                Some(rps_values[idx])
            };
            rps_percentiles.insert(key, val);
        }

        // details: DNS
        // Collect dns durations
        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::NAN);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NAN);

        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::NAN);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NAN);

        // Build JSON
        let mut summary = json!({
            "successRate": if success_rate.is_nan() { serde_json::Value::Null } else { json!(success_rate) },
            "total": total_elapsed,
            "slowest": if slowest.is_infinite() { serde_json::Value::Null } else { json!(slowest) },
            "fastest": if fastest.is_infinite() { serde_json::Value::Null } else { json!(fastest) },
            "average": if average.is_nan() { serde_json::Value::Null } else { json!(average) },
            "requestsPerSec": requests_per_sec,
            "totalData": total_data_val,
            "sizePerRequest": if success_count>0 { json!(total_data_val / success_count) } else { serde_json::Value::Null },
            "sizePerSec": if total_elapsed>0.0 { json!(total_data_val as f64 / total_elapsed) } else { json!(0.0) },
        });

        // For breakdown
        let mut json_obj = serde_json::Map::new();
        json_obj.insert("summary".to_string(), summary);

        // histograms
        let hist_json: serde_json::Map<String, serde_json::Value> = hist_counts.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
        json_obj.insert("responseTimeHistogram".to_string(), serde_json::Value::Object(hist_json));

        let lp_json: serde_json::Map<String, serde_json::Value> = latency_percentiles.iter().map(|(k,v)| {
            (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })
        }).collect();
        json_obj.insert("latencyPercentiles".to_string(), serde_json::Value::Object(lp_json));

        if stats_breakdown {
            // Need successful vs not successful
            let mut success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            let mut not_success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && (r.status>=400 || r.status>=500)).map(|r| r.duration).collect();
            not_success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());

            // histograms for success breakdown
            let mut success_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !success_durations.is_empty() {
                let min = success_durations.first().cloned().unwrap();
                let max = success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let key = format!("{}", edge);
                    success_hist.insert(key, 0);
                }
                for d in &success_durations {
                    if step==0.0 {
                        if let Some(first_key) = success_hist.keys().next().cloned() {
                            *success_hist.get_mut(&first_key).unwrap() +=1;
                        }
                    } else {
                        let idx = ((d - success_hist.keys().next().map(|k| k.parse::<f64>().unwrap_or(0.0)).unwrap_or(0.0))/step).floor() as usize;
                        // simplify: use same as before via index
                        let idx = std::cmp::min(idx, 10);
                        if let Some(k) = success_hist.keys().nth(idx).cloned() {
                            *success_hist.get_mut(&k).unwrap() +=1;
                        }
                    }
                }
            } else {
                success_hist.insert("NaN".to_string(), 0);
            }

            let mut not_success_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !not_success_durations.is_empty() {
                let min = not_success_durations.first().cloned().unwrap();
                let max = not_success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let key = format!("{}", edge);
                    not_success_hist.insert(key, 0);
                }
                for d in &not_success_durations {
                    if step==0.0 {
                        if let Some(first_key) = not_success_hist.keys().next().cloned() {
                            *not_success_hist.get_mut(&first_key).unwrap() +=1;
                        }
                    } else {
                        let idx = ((d - not_success_durations[0])/step).floor() as usize;
                        let idx = std::cmp::min(idx, 10);
                        if let Some(k) = not_success_hist.keys().nth(idx).cloned() {
                            *not_success_hist.get_mut(&k).unwrap() +=1;
                        }
                    }
                }
            } else {
                not_success_hist.insert("NaN".to_string(), 0);
            }

            let mut success_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            for &p in &percentiles {
                let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if p==0.10 { "10" } else if p==0.25 { "25" } else if p==0.50 { "50" } else if p==0.75 { "75" } else if p==0.90 { "90" } else if p==0.95 { "95" } else if p==0.99 { "99" } else { "" });
                let val = if success_durations.is_empty() {
                    None
                } else {
                    let idx = ((p * success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, success_durations.len()-1);
                    Some(success_durations[idx])
                };
                success_lp.insert(key, val);
            }

            let mut not_success_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            for &p in &percentiles {
                let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if p==0.10 { "10" } else if p==0.25 { "25" } else if p==0.50 { "50" } else if p==0.75 { "75" } else if p==0.90 { "90" } else if p==0.95 { "95" } else if p==0.99 { "99" } else { "" });
                let val = if not_success_durations.is_empty() {
                    None
                } else {
                    let idx = ((p * not_success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, not_success_durations.len()-1);
                    Some(not_success_durations[idx])
                };
                not_success_lp.insert(key, val);
            }

            let success_hist_json: serde_json::Map<String, serde_json::Value> = success_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
            json_obj.insert("responseTimeHistogramSuccessful".to_string(), serde_json::Value::Object(success_hist_json));
            let success_lp_json: serde_json::Map<String, serde_json::Value> = success_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect();
            json_obj.insert("latencyPercentilesSuccessful".to_string(), serde_json::Value::Object(success_lp_json));

            let not_success_hist_json: serde_json::Map<String, serde_json::Value> = not_success_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
            json_obj.insert("responseTimeHistogramNotSuccessful".to_string(), serde_json::Value::Object(not_success_hist_json));
            let not_success_lp_json: serde_json::Map<String, serde_json::Value> = not_success_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect();
            json_obj.insert("latencyPercentilesNotSuccessful".to_string(), serde_json::Value::Object(not_success_lp_json));
        }

        // rps
        let rps_obj = json!({
            "mean": if rps_mean.is_nan() || rps_mean.is_infinite() { serde_json::Value::Null } else { json!(rps_mean) },
            "stddev": match rps_stddev { Some(v) => json!(v), None => serde_json::Value::Null },
            "max": if rps_max.is_infinite() { serde_json::Value::Null } else { json!(rps_max) },
            "min": if rps_min.is_infinite() { serde_json::Value::Null } else { json!(rps_min) },
            "percentiles": serde_json::Value::Object(rps_percentiles.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect())
        });
        json_obj.insert("rps".to_string(), rps_obj);

        // details
        let details_obj = json!({
            "DNSDialup": {
                "average": if dialup_avg.is_nan() { serde_json::Value::Null } else { json!(dialup_avg) },
                "fastest": if dialup_fast.is_infinite() || dialup_fast.is_nan() { serde_json::Value::Null } else { json!(dialup_fast) },
                "slowest": if dialup_slow.is_infinite() || dialup_slow.is_nan() { serde_json::Value::Null } else { json!(dialup_slow) },
            },
            "DNSLookup": {
                "average": if dns_avg.is_nan() { serde_json::Value::Null } else { json!(dns_avg) },
                "fastest": if dns_fast.is_infinite() || dns_fast.is_nan() { serde_json::Value::Null } else { json!(dns_fast) },
                "slowest": if dns_slow.is_infinite() || dns_slow.is_nan() { serde_json::Value::Null } else { json!(dns_slow) },
            }
        });
        json_obj.insert("details".to_string(), details_obj);

        let status_json: serde_json::Map<String, serde_json::Value> = status_dist.iter().map(|(k,v)| (k.to_string(), json!(*v))).collect();
        json_obj.insert("statusCodeDistribution".to_string(), serde_json::Value::Object(status_json));

        let error_json: serde_json::Map<String, serde_json::Value> = error_dist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
        json_obj.insert("errorDistribution".to_string(), serde_json::Value::Object(error_json));

        output_string = serde_json::to_string_pretty(&serde_json::Value::Object(json_obj)).unwrap();

    } else if output_format == "csv" {
        let mut s = String::new();
        s.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
        for r in results_vec.iter() {
            if r.error.is_some() { continue; }
            s.push_str(&format!("{:.9},{:.9},{:.9},{:.9},{:.9},{},{}\n",
                r.start,
                r.dns_lookup.unwrap_or(0.0),
                r.dns_dialup.unwrap_or(0.0),
                r.response_delay,
                r.duration,
                r.bytes,
                r.status
            ));
        }
