            s.push_str(&format!("  Total:\t{:.4} {}\n", convert_time(total_elapsed, &tu), tu));
            s.push_str(&format!("  Slowest:\t{:.4} {}\n", if slowest.is_infinite() { f64::NEG_INFINITY } else { convert_time(slowest, &tu) }, tu));
            s.push_str(&format!("  Fastest:\t{:.4} {}\n", if fastest.is_infinite() { f64::INFINITY } else { convert_time(fastest, &tu) }, tu));
            s.push_str(&format!("  Average:\t{:.4} {}\n", if average.is_nan() { f64::NAN } else { convert_time(average, &tu) }, tu));
        } else {
            // auto detection: if total <1ms => us, <1s => ms? Let's replicate original behavior: For small durations, they show us, for larger ms, sec etc.
            // We'll implement simple: choose unit automatically based on average or total?
            // Observing original: for total 3950 us, fastest 295 us, they showed us for all.
            // For total ~8ms, they showed ms.
            // So auto mode: if total <0.001 (1ms) => us, <1 => ms, <60 => ms? Actually second case total 5ms showed ms, total 1 sec showed sec.
            // Let's do: if max <0.001 => us, else if max <1 => ms, else sec.

            let unit = if slowest < 0.001 { "us" } else if slowest < 1.0 { "ms" } else { "sec" };
            // but need to convert each separately? In text they use same unit for all? In examples, they had mix? Actually they had same unit for all fields (total in us, slowest in us etc) when auto.
            // So use same unit determined from total? Let's use average.

            // We'll implement function to auto-format: returns string like "3950.3070 us" with appropriate unit and 4 decimal.

            // For simplicity, we'll use auto unit per value? But original uses same unit? Let's check: in earlier capture with total 8.9137 ms, slowest 0.9221 ms etc – all ms.
            // So we need to determine unit globally.

            let auto_unit = if total_elapsed < 0.000001 { "ns" } else if total_elapsed < 0.001 { "us" } else if total_elapsed < 1.0 { "ms" } else { "sec" };

            s.push_str(&format!("  Total:\t{}\n", format_time(total_elapsed, auto_unit)));
            s.push_str(&format!("  Slowest:\t{}\n", if slowest.is_infinite() { "-inf ns".to_string() } else if fastest.is_infinite() { "inf ns".to_string() } else { format_time(slowest, auto_unit) }));
            s.push_str(&format!("  Fastest:\t{}\n", if fastest.is_infinite() { "inf ns".to_string() } else if slowest.is_infinite() { "-inf ns".to_string() } else { format_time(fastest, auto_unit) }));
