            for i in 0..=10 {
                let edge = if step==0.0 { min } else { min + step*i as f64 };
                let count = bins[i];
                let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                // format edge with appropriate unit
                let time_str = if let Some(tu) = &time_unit {
                    format!("{:.4} {}", convert_time(edge, tu), tu)
                } else {
                    // auto: determine unit from edge? Use same as earlier auto detection based on max?
                    // We'll use format_time with auto unit determined from edge's magnitude? But original histogram uses unit per edge based on auto?
