        if let Some(tu) = &time_unit {
            s.push_str(&format!("  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dialup_avg.is_nan() { f64::NAN } else { convert_time(dialup_avg, tu) },
                tu,
                if dialup_fast.is_infinite() { f64::INFINITY } else { convert_time(dialup_fast, tu) },
                tu,
                if dialup_slow.is_infinite() && dialup_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dialup_slow, tu) },
                tu
            ));
            s.push_str(&format!("  DNS-lookup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dns_avg.is_nan() { f64::NAN } else { convert_time(dns_avg, tu) },
                tu,
                if dns_fast.is_infinite() { f64::INFINITY } else { convert_time(dns_fast, tu) },
                tu,
                if dns_slow.is_infinite() && dns_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dns_slow, tu) },
                tu
            ));
        } else {
            s.push_str(&format!("  DNS+dialup:\t{}, {}, {}\n",
                format_time_auto(dialup_avg),
                format_time_auto(dialup_fast),
