                let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                // format edge with appropriate unit
                let time_str = if let Some(tu) = &time_unit {
                    format!("{:.4} {}", convert_time(edge, tu), tu)
                } else {
                    // auto: determine unit from edge? Use same as earlier auto detection based on max?
                    // We'll use format_time with auto unit determined from edge's magnitude? But original histogram uses unit per edge based on auto?
                    // In earlier examples, histogram with us showed "295.345 us"
                    // So we can auto format each edge individually? Let's just use format_time_auto which picks unit per value.
                    format_time_auto(edge)
                };
                s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
            }
        }
        s.push_str("\n");
        s.push_str("Response time distribution:\n");
        let percentiles_vals = [0.10,0.25,0.50,0.75,0.90,0.95,0.99,0.999,0.9999];
        let percentile_labels = ["10.00%","25.00%","50.00%","75.00%","90.00%","95.00%","99.00%","99.90%","99.99%"];
        for (i,&p) in percentiles_vals.iter().enumerate() {
            let val = if durations.is_empty() {
                "NaN ns".to_string()
            } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                let d = durations[idx];
                if let Some(tu) = &time_unit {
                    format!("{:.4} {}", convert_time(d, tu), tu)
                } else {
                    format_time_auto(d)
                }
            };
            s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
        }
        s.push_str("\n");
        s.push_str("\n");
        if stats_breakdown {
            // 2xx only
            let mut success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (2xx only):\n");
            if success_durations.is_empty() {
                s.push_str("    NaN ns [0] |\n".repeat(11));
            } else {
                let min = success_durations.first().cloned().unwrap();
                let max = success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &success_durations {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let max_count = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let count = bins[i];
                    let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let time_str = if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(edge, tu), tu)
                    } else {
                        format_time_auto(edge)
                    };
                    s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (2xx only):\n");
            for (i,&p) in percentiles_vals.iter().enumerate() {
                let val = if success_durations.is_empty() {
                    "NaN ns".to_string()
                } else {
                    let idx = ((p * success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, success_durations.len()-1);
                    let d = success_durations[idx];
                    if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(d, tu), tu)
                    } else {
                        format_time_auto(d)
                    }
                };
                s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
            }
            s.push_str("\n");
            s.push_str("\n");
            // 4xx+5xx
            let mut not_success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=400).map(|r| r.duration).collect();
            not_success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (4xx + 5xx only):\n");
            if not_success_durations.is_empty() {
                s.push_str("    NaN ns [0] |\n".repeat(11));
            } else {
                let min = not_success_durations.first().cloned().unwrap();
                let max = not_success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &not_success_durations {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let max_count = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let count = bins[i];
                    let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let time_str = if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(edge, tu), tu)
                    } else {
                        format_time_auto(edge)
                    };
                    s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (4xx + 5xx only):\n");
            for (i,&p) in percentiles_vals.iter().enumerate() {
                let val = if not_success_durations.is_empty() {
                    "NaN ns".to_string()
                } else {
                    let idx = ((p * not_success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, not_success_durations.len()-1);
                    let d = not_success_durations[idx];
                    if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(d, tu), tu)
                    } else {
                        format_time_auto(d)
                    }
                };
                s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
            }
            s.push_str("\n");
            s.push_str("\n");
        }

        s.push_str("\n");
        s.push_str("Details (average, fastest, slowest):\n");
        // DNS+dialup
        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);

        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);

        if let Some(tu) = &time_unit {
            s.push_str(&format!("  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dialup_avg.is_nan() { f64::NAN } else { convert_time(dialup_avg, tu) },
                tu,
                if dialup_fast.is_infinite() { f64::INFINITY } else { convert_time(dialup_fast, tu) },
                tu,
                if dialup_slow.is_infinite() && dialup_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dialup_slow, tu) },
                tu
            ));
            s.push_str(&format!("  DNS-lookup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dns_avg.is_nan() { f64::NAN } else { convert_time(dns_avg, tu) },
                tu,
                if dns_fast.is_infinite() { f64::INFINITY } else { convert_time(dns_fast, tu) },
                tu,
                if dns_slow.is_infinite() && dns_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dns_slow, tu) },
                tu
            ));
        } else {
            s.push_str(&format!("  DNS+dialup:\t{}, {}, {}\n",
                format_time_auto(dialup_avg),
                format_time_auto(dialup_fast),
                format_time_auto(dialup_slow)
            ));
            s.push_str(&format!("  DNS-lookup:\t{}, {}, {}\n",
                format_time_auto(dns_avg),
                format_time_auto(dns_fast),
                format_time_auto(dns_slow)
            ));
        }
        s.push_str("\n");
        s.push_str("Status code distribution:\n");
        for (code, count) in status_dist.iter() {
            s.push_str(&format!("  [{}] {} responses\n", code, count));
        }
        if !error_dist.is_empty() {
            s.push_str("\n");
            s.push_str("Error distribution:\n");
            for (msg, count) in error_dist.iter() {
                s.push_str(&format!("  [{}] {}\n", count, msg));
            }
        }

        output_string = s;
    }

    // Handle db-url
    if let Some(db_path) = db_url {
        // Write to sqlite using Python? We'll implement simple sqlite via calling python -c
        // Since we don't have rusqlite, we will use std::process to invoke python3 to create db
        // Format: python3 - <<PY to create table and insert
        // But we can attempt to write ourselves using manual sqlite file? Simpler to use python.

        // Prepare rows: only succeeded? Original stored both successful? In earlier test with mix of 200 and 500, it stored both (status 200 and 500) – yes it stored all succeeded? Actually error distribution doesn't store, but status 500 is considered success? In oha, successRate includes all? In earlier test, successRate 100% even with 500 – so 500 counted as success. So db stores all with status !=0 and no error.

        // For each result that is not error, insert.

        let mut insert_values: Vec<String> = Vec::new();
        for r in results_vec.iter() {
            if r.error.is_none() {
                // url = path only? In earlier db, url was '/' not full URL. So store path? Let's store path part.
                let url_for_db = match url::Url::parse(&r.url) {
                    Ok(u) => u.path().to_string(),
                    Err(_) => r.url.clone(),
                };
                let start = r.start;
                let start_lc = match r.start_latency_correction {
                    Some(v) => format!("{}", v),
                    None => "NULL".to_string(),
                };
                let end = r.end;
                let duration = r.duration;
                let status = r.status;
                let len = r.bytes;
                let run = run_unix_timestamp;
                // Escape single quotes in url
                let url_escaped = url_for_db.replace('\'', "''");
                if start_lc=="NULL" {
                    insert_values.push(format!("('{}',{},{},NULL,{},{},{},{},{})", url_escaped, start, start, end, duration, status, len, run));
                    // Wait original had start, start_latency_correction, end, duration – note second start column is start? Actually schema: url, start, start_latency_correction, end, duration
                    // Our first query earlier: we had start 0.0019, second None, third 0.0027, fourth 0.00082 – second start column? Actually we mapped as start, start_latency_correction, end, duration – but in our insert we have start duplicated? Let's correct: schema is (url, start, start_latency_correction, end, duration, status, len_bytes, run)
                    // So we need start, start_lc, end, duration
                    // In our push above we have (url, start, start, end, duration) duplicate? We need (url, start, start_lc, end, duration)
                    // So we should have (url, start, start_lc, end, duration)
                    // Our current string has 8 values? Let's count: ('{}',{},{},NULL,{},{},{},{}) – that's url, start, start, NULL, end, duration, status, len, run = 9? Actually we have url plus 7 numbers = 8 columns? Let's recount.
                } else {
                    insert_values.push(format!("('{}',{},{},{},{},{},{},{})", url_escaped, start, start_lc, end, duration, status, len, run));
                }
            }
        }

        // Now fix duplicate case
        // Rebuild insert_values correctly
        let mut insert_values_correct: Vec<String> = Vec::new();
        for r in results_vec.iter() {
            if r.error.is_none() {
                let url_for_db = match url::Url::parse(&r.url) {
                    Ok(u) => u.path().to_string(),
                    Err(_) => r.url.clone(),
                };
                let url_escaped = url_for_db.replace('\'', "''");
                let start = r.start;
                let end = r.end;
                let duration = r.duration;
                let status = r.status;
                let len = r.bytes;
                let run = run_unix_timestamp;
                match r.start_latency_correction {
                    Some(lc) => {
                        insert_values_correct.push(format!("('{}',{},{},{},{},{},{},{})", url_escaped, start, lc, end, duration, status, len, run));
                    },
                    None => {
                        insert_values_correct.push(format!("('{}',{},NULL,{},{},{},{},{})", url_escaped, start, end, duration, status, len, run));
                    }
                }
            }
        }

        // Use python to write db
        let mut python_code = String::new();
        python_code.push_str("import sqlite3, sys\n");
        python_code.push_str(&format!("con=sqlite3.connect(r\"{}\")\n", db_path.replace('"', "\\\"")));
        python_code.push_str("cur=con.cursor()\n");
        python_code.push_str("cur.execute('''CREATE TABLE IF NOT EXISTS oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )''')\n");
        for val in insert_values_correct {
            python_code.push_str(&format!("cur.execute('INSERT INTO oha VALUES {}')\n", val));
        }
        python_code.push_str("con.commit()\n");
        python_code.push_str("con.close()\n");

        let mut child = std::process::Command::new("python3")
            .arg("-c")
            .arg(python_code)
            .spawn();
        if let Ok(mut child) = child {
            let _ = child.wait();
        }

        // Also print "Storing results to ..." to stderr? Original printed that message? In earlier capture, after running with db-url, it printed "Storing results to /tmp/test.db" to stdout? Actually it printed to stdout? Let's see: In earlier capture, after summary, it printed "Storing results to /tmp/test.db" – that was after status distribution. So we should print that to stdout? Let's check: original with db-url had message after status distribution in stdout? In capture, after summary and status distribution, there was line "Storing results to /tmp/test.db". That likely goes to stderr or stdout? In our capture, it was printed as part of stdout? We saw tail included it. So we should append to output_string.

        output_string.push_str(&format!("\nStoring results to {}\n", db_path));
    }

    // Finally output to file or stdout
    if let Some(out_path) = output_path {
        if let Err(e) = std::fs::write(&out_path, output_string.as_bytes()) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else {
        print!("{}", output_string);
    }
}

fn build_cmd() -> Command {
    Command::new("oha").bin_name("executable")
        .version("1.12.1")
        .about("Ohayou(おはよう), HTTP load generator, inspired by rakyll/hey with tui animation.")
        .arg(Arg::new("URL").help("Target URL or file with multiple URLs.").required(true))
        .arg(Arg::new("n").short('n').value_name("N_REQUESTS").default_value("200").help("Number of requests to run. Accepts plain numbers or suffixes: k = 1,000, m = 1,000,000 (e.g. 10k, 1m)."))
        .arg(Arg::new("c").short('c').value_name("N_CONNECTIONS").default_value("50").help("Number of connections to run concurrently. You may should increase limit to number of open files for larger `-c`."))
        .arg(Arg::new("p").short('p').value_name("N_HTTP2_PARALLEL").default_value("1").help("Number of parallel requests to send on HTTP/2. `oha` will run c * p concurrent workers in total."))
        .arg(Arg::new("z").short('z').value_name("DURATION").help("Duration of application to send requests.\nOn HTTP/1, When the duration is reached, ongoing requests are aborted and counted as \"aborted due to deadline\"\nYou can change this behavior with `-w` option.\nCurrently, on HTTP/2, When the duration is reached, ongoing requests are waited. `-w` option is ignored.\nExamples: -z 10s -z 3m.").conflicts_with("n"))
        .arg(Arg::new("wait").short('w').long("wait-ongoing-requests-after-deadline").action(ArgAction::SetTrue).help("When the duration is reached, ongoing requests are waited"))
        .arg(Arg::new("q").short('q').value_name("QUERY_PER_SECOND").help("Rate limit for all, in queries per second (QPS)").conflicts_with_all(["burst-delay","burst-rate"]))
        .arg(Arg::new("burst-delay").long("burst-delay").value_name("BURST_DURATION").help("Introduce delay between a predefined number of requests.\nNote: If qps is specified, burst will be ignored"))
        .arg(Arg::new("burst-rate").long("burst-rate").value_name("BURST_REQUESTS").help("Rates of requests for burst. Default is 1\nNote: If qps is specified, burst will be ignored").requires("burst-delay"))
        .arg(Arg::new("rand-regex-url").long("rand-regex-url").action(ArgAction::SetTrue).help("Generate URL by rand_regex crate but dot is disabled for each query e.g. http://127.0.0.1/[a-z][a-z][0-9]. Currently dynamic scheme, host and port with keep-alive do not work well. See https://docs.rs/rand_regex/latest/rand_regex/struct.Regex.html for details of syntax."))
        .arg(Arg::new("urls-from-file").long("urls-from-file").action(ArgAction::SetTrue).help("Read the URLs to query from a file"))
        .arg(Arg::new("max-repeat").long("max-repeat").value_name("MAX_REPEAT").default_value("4").help("A parameter for the '--rand-regex-url'. The max_repeat parameter gives the maximum extra repeat counts the x*, x+ and x{n,} operators will become."))
        .arg(Arg::new("dump-urls").long("dump-urls").value_name("DUMP_URLS").help("Dump target Urls <DUMP_URLS> times to debug --rand-regex-url"))
        .arg(Arg::new("latency-correction").long("latency-correction").action(ArgAction::SetTrue).help("Correct latency to avoid coordinated omission problem. It's ignored if -q is not set."))
        .arg(Arg::new("no-tui").long("no-tui").action(ArgAction::SetTrue).help("No realtime tui"))
        .arg(Arg::new("fps").long("fps").value_name("FPS").default_value("16").help("Frame per second for tui."))
        .arg(Arg::new("method").short('m').long("method").value_name("METHOD").default_value("GET").help("HTTP method"))
        .arg(Arg::new("headers").short('H').value_name("HEADERS").action(ArgAction::Append).help("Custom HTTP header. Examples: -H \"foo: bar\""))
        .arg(Arg::new("proxy-headers").long("proxy-header").value_name("PROXY_HEADERS").action(ArgAction::Append).help("Custom Proxy HTTP header. Examples: --proxy-header \"foo: bar\""))
        .arg(Arg::new("timeout").short('t').value_name("TIMEOUT").help("Timeout for each request. Default to infinite."))
        .arg(Arg::new("connect-timeout").long("connect-timeout").value_name("CONNECT_TIMEOUT").default_value("5s").help("Timeout for establishing a new connection. Default to 5s."))
        .arg(Arg::new("accept").short('A').value_name("ACCEPT_HEADER").help("HTTP Accept Header."))
        .arg(Arg::new("body-string").short('d').value_name("BODY_STRING").help("HTTP request body.").conflicts_with_all(["body-path","body-lines","form"]))
        .arg(Arg::new("body-path").short('D').value_name("BODY_PATH").help("HTTP request body from file.").conflicts_with_all(["body-string","body-lines","form"]))
        .arg(Arg::new("body-lines").short('Z').value_name("BODY_PATH_LINES").help("HTTP request body from file line by line.").conflicts_with_all(["body-string","body-path","form"]))
        .arg(Arg::new("form").short('F').long("form").value_name("FORM").action(ArgAction::Append).help("Specify HTTP multipart POST data (curl compatible). Examples: -F 'name=value' -F 'file=@path/to/file'"))
        .arg(Arg::new("content-type").short('T').value_name("CONTENT_TYPE").help("Content-Type."))
        .arg(Arg::new("basic-auth").short('a').value_name("BASIC_AUTH").help("Basic authentication (username:password), or AWS credentials (access_key:secret_key)"))
        .arg(Arg::new("aws-session").long("aws-session").value_name("AWS_SESSION").help("AWS session token"))
        .arg(Arg::new("aws-sigv4").long("aws-sigv4").value_name("AWS_SIGV4").help("AWS SigV4 signing params (format: aws:amz:region:service)"))
        .arg(Arg::new("proxy").short('x').value_name("PROXY").help("HTTP proxy"))
        .arg(Arg::new("proxy-http-version").long("proxy-http-version").value_name("PROXY_HTTP_VERSION").help("HTTP version to connect to proxy. Available values 0.9, 1.0, 1.1, 2."))
        .arg(Arg::new("proxy-http2").long("proxy-http2").action(ArgAction::SetTrue).conflicts_with("proxy-http-version").help("Use HTTP/2 to connect to proxy. Shorthand for --proxy-http-version=2"))
        .arg(Arg::new("http-version").long("http-version").value_name("HTTP_VERSION").help("HTTP version. Available values 0.9, 1.0, 1.1, 2, 3"))
        .arg(Arg::new("http2").long("http2").action(ArgAction::SetTrue).conflicts_with("http-version").help("Use HTTP/2. Shorthand for --http-version=2"))
        .arg(Arg::new("host").long("host").value_name("HOST").help("HTTP Host header"))
        .arg(Arg::new("disable-compression").long("disable-compression").action(ArgAction::SetTrue).help("Disable compression."))
        .arg(Arg::new("redirect").short('r').long("redirect").value_name("REDIRECT").default_value("10").help("Limit for number of Redirect. Set 0 for no redirection. Redirection isn't supported for HTTP/2."))
        .arg(Arg::new("disable-keepalive").long("disable-keepalive").action(ArgAction::SetTrue).help("Disable keep-alive, prevents re-use of TCP connections between different HTTP requests. This isn't supported for HTTP/2."))
        .arg(Arg::new("no-pre-lookup").long("no-pre-lookup").action(ArgAction::SetTrue).help("*Not* perform a DNS lookup at beginning to cache it"))
        .arg(Arg::new("ipv6").long("ipv6").action(ArgAction::SetTrue).help("Lookup only ipv6."))
        .arg(Arg::new("ipv4").long("ipv4").action(ArgAction::SetTrue).help("Lookup only ipv4."))
        .arg(Arg::new("cacert").long("cacert").value_name("CACERT").help("(TLS) Use the specified certificate file to verify the peer. Native certificate store is used even if this argument is specified."))
        .arg(Arg::new("cert").long("cert").value_name("CERT").help("(TLS) Use the specified client certificate file. --key must be also specified").requires("key"))
        .arg(Arg::new("key").long("key").value_name("KEY").help("(TLS) Use the specified client key file. --cert must be also specified").requires("cert"))
        .arg(Arg::new("insecure").long("insecure").action(ArgAction::SetTrue).help("Accept invalid certs."))
        .arg(Arg::new("connect-to").long("connect-to").value_name("CONNECT_TO").action(ArgAction::Append).help("Override DNS resolution and default port numbers with strings like 'example.org:443:localhost:8443'\nNote: if used several times for the same host:port:target_host:target_port, a random choice is made"))
        .arg(Arg::new("no-color").long("no-color").action(ArgAction::SetTrue).help("Disable the color scheme. [env: NO_COLOR=]"))
        .arg(Arg::new("unix-socket").long("unix-socket").value_name("UNIX_SOCKET").help("Connect to a unix socket instead of the domain in the URL. Only for non-HTTPS URLs."))
        .arg(Arg::new("stats-success-breakdown").long("stats-success-breakdown").action(ArgAction::SetTrue).help("Include a response status code successful or not successful breakdown for the time histogram and distribution statistics"))
        .arg(Arg::new("db-url").long("db-url").value_name("DB_URL").help("Write succeeded requests to sqlite database url E.G test.db"))
        .arg(Arg::new("debug").long("debug").action(ArgAction::SetTrue).help("Perform a single request and dump the request and response"))
        .arg(Arg::new("output").short('o').long("output").value_name("OUTPUT").help("Output file to write the results to. If not specified, results are written to stdout."))
        .arg(Arg::new("output-format").long("output-format").value_name("OUTPUT_FORMAT").default_value("text").hide_default_value(true).hide_possible_values(true).help("Output format [default: text] [possible values: text, json, csv, quiet]"))
        .arg(Arg::new("time-unit").short('u').long("time-unit").value_name("TIME_UNIT").hide_possible_values(true).help("Time unit to be used. If not specified, the time unit is determined automatically. This option affects only text format. [possible values: ns, us, ms, s, m, h]"))
}

fn parse_n_requests(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("invalid digit found in string".to_string());
    }
    let lower = s.to_lowercase();
    let (num_part, mult) = if lower.ends_with('k') {
        (&s[..s.len()-1], 1000)
    } else if lower.ends_with('m') {
        (&s[..s.len()-1], 1_000_000)
    } else {
        (s, 1)
    };
    if num_part.is_empty() {
        return Err("invalid digit found in string".to_string());
    }
    match num_part.parse::<u64>() {
        Ok(v) => Ok(v * mult),
        Err(_) => Err("invalid digit found in string".to_string()),
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }
    // Find number prefix
    let mut num_end = 0;
    let mut has_digit = false;
    let mut has_dot = false;
    for (i,c) in s.char_indices() {
        if c.is_ascii_digit() {
            has_digit = true;
            num_end = i + c.len_utf8();
        } else if c=='.' {
            if has_dot { break; }
            has_dot = true;
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if !has_digit || num_end==0 {
        return Err("expected number at 0".to_string());
    }
    let num_str = &s[..num_end];
    let unit_str = s[num_end..].trim();
    if unit_str.is_empty() {
        return Err("time unit needed, for example 10sec or 10ms".to_string());
    }
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let mult = match unit_str {
        "ns" => 1e-9,
        "us" | "µs" | "μs" => 1e-6,
        "ms" | "milli" | "millis" | "msec" | "msecs" | "millisecond" | "milliseconds" => 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => 1.0,
        "m" | "min" | "mins" | "minute" | "minutes" => 60.0,
        "h" | "hour" | "hours" => 3600.0,
        "d" | "day" | "days" => 86400.0,
        "w" | "week" | "weeks" => 604800.0,
        "month" | "months" => 2629746.0,
        "y" | "year" | "years" => 31556952.0,
        _ => {
            return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit_str));
        }
    };
    Ok(Duration::from_secs_f64(num * mult))
}

fn generate_rand_url(pattern: &str, max_repeat: usize) -> String {
    // Simplified implementation: similar to earlier but respecting max_repeat for * and +
    use rand::Rng;
    let mut rng = rand::thread_rng();
    // We want to treat dot as disabled: so '.' in pattern should be treated as literal dot, not regex.
    // For simplicity, we will just not treat '.' specially, but we already only handle brackets.

    let mut out = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '[' {
            // find closing ]
            let mut j = i+1;
            while j < chars.len() && chars[j] != ']' {
                j+=1;
            }
            if j>=chars.len() {
                out.push(c);
                i+=1;
                continue;
            }
            let inner: String = chars[i+1..j].iter().collect();
            let mut candidates: Vec<char> = Vec::new();
            let inner_chars: Vec<char> = inner.chars().collect();
            let mut k = 0;
            while k < inner_chars.len() {
                let ch = inner_chars[k];
                if k+2 < inner_chars.len() && inner_chars[k+1]=='-' {
                    let start = ch;
                    let end = inner_chars[k+2];
                    if start <= end {
                        for rc in (start as u8)..=(end as u8) {
                            candidates.push(rc as char);
                        }
                    }
                    k+=3;
                } else {
                    candidates.push(ch);
                    k+=1;
                }
            }
            if candidates.is_empty() {
                candidates.push('a');
            }
            // check quantifier after ]
            let mut repeat = 1;
            let mut quant = ' ';
            if j+1 < chars.len() {
                let next = chars[j+1];
                if next=='*' || next=='+' || next=='?' {
                    quant = next;
                    // need to handle repeat
                } else if next=='{' {
                    // parse {n} or {n,} or {n,m}
                    let mut end_brace = j+2;
                    while end_brace < chars.len() && chars[end_brace]!='}' {
                        end_brace+=1;
                    }
                    if end_brace < chars.len() {
                        let brace_content: String = chars[j+2..end_brace].iter().collect();
                        // parse first number
                        // for simplicity, treat as exactly that number or random up to that? We'll treat as fixed.
                        if let Ok(n) = brace_content.split(',').next().unwrap_or("1").trim().parse::<usize>() {
                            repeat = n;
                        }
                        // advance i to end_brace
                        j = end_brace;
                    }
                }
            }
            if quant=='*' {
                // 0 to max_repeat
                repeat = rng.gen_range(0..=max_repeat);
                j+=1;
            } else if quant=='+' {
                // 1 to max_repeat+1? Original says max_repeat gives max extra repeat counts the x*, x+ and x{n,} operators will become.
                // So for x* and x+ and x{n,}, max_repeat is max extra.
                // For +, at least 1, plus extra up to max_repeat
                repeat = 1 + rng.gen_range(0..=max_repeat);
                j+=1;
            } else if quant=='?' {
                repeat = if rng.gen_bool(0.5) {1} else {0};
                j+=1;
            }

            for _ in 0..repeat {
                let idx = rng.gen_range(0..candidates.len());
                out.push(candidates[idx]);
            }

            i = j+1;
        } else if c == '.' {
            // dot disabled -> treat as literal dot
            out.push('.');
            i+=1;
        } else {
            out.push(c);
            i+=1;
        }
    }
    out
}

fn do_debug_request(matches: &clap::ArgMatches, url_str: &str, out_buf: &mut Vec<u8>, connect_timeout: Duration, timeout_opt: Option<Duration>, _burst_delay: Option<Duration>, _qps: Option<f64>, _redirect_limit: usize, _max_repeat: usize) -> Result<(), String> {
    // Build and print request, then perform it.
    // We'll reuse logic from earlier but write to out_buf instead of stdout directly via println!
    // For simplicity, we'll use println! macro redirected? We'll build strings and write to out_buf.

    let parsed = match url::Url::parse(url_str) {
        Ok(u) => u,
        Err(e) => return Err(format!("relative URL without a base")),
    };
    let host = parsed.host_str().ok_or("no host")?.to_string();
    let port = parsed.port_or_known_default().unwrap_or(80);
    let path = if parsed.path().is_empty() { "/" } else { parsed.path() };
    let query = if let Some(q) = parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };
    let method = matches.get_one::<String>("method").map(|s| s.as_str()).unwrap_or("GET");
    let mut headers_vec: Vec<(String,String)> = Vec::new();
    if let Some(hs) = matches.get_many::<String>("headers") {
        for h in hs {
            if let Some((k,v)) = h.split_once(':') {
                headers_vec.push((k.trim().to_string(), v.trim().to_string()));
            }
        }
    }
    if let Some(a) = matches.get_one::<String>("accept") {
        headers_vec.push(("accept".to_string(), a.clone()));
    }
    if let Some(ct) = matches.get_one::<String>("content-type") {
        headers_vec.push(("content-type".to_string(), ct.clone()));
    }
    if let Some(h) = matches.get_one::<String>("host") {
        headers_vec.push(("host".to_string(), h.clone()));
    } else {
        headers_vec.push(("host".to_string(), format!("{}:{}", host, port)));
    }
    if let Some(auth) = matches.get_one::<String>("basic-auth") {
        // Check if it's AWS? If aws-sigv4 present, then it's AWS credentials
        if matches.contains_id("aws-sigv4") {
            // AWS sigv4 handling
            let sigv4_str = matches.get_one::<String>("aws-sigv4").unwrap();
            // format: aws:amz:region:service
            let parts: Vec<&str> = sigv4_str.split(':').collect();
            if parts.len()!=4 {
                return Err("invalid aws-sigv4 format".to_string());
            }
            let region = parts[2];
            let service = parts[3];
            // For debug, we need to generate authorization header
            // We'll implement simple AWS4 signing using std
            // Use time as 20260908T... based on current time? Original used current date.
            // For simplicity, we use fixed date for testing? But we should use current time.
            // We'll need to compute signature.

            // Placeholder: generate dummy signature for now – but we need realistic for earlier test we did, it generated valid header with date.
            // To match original, we need to compute HMAC-SHA256.

            // We'll implement SHA256 and HMAC.

            let access_key = auth.split(':').next().unwrap_or("");
            let secret_key = auth.split(':').nth(1).unwrap_or("");
            let session_token = matches.get_one::<String>("aws-session").map(|s| s.as_str());

            // Build canonical request
            let now = chrono::Utc::now();
            let amz_date = now.format("%Y%m%dT%H%M%SZ").to_string();
            let date_stamp = now.format("%Y%m%d").to_string();

            // For simplicity, we assume payload empty
            let payload_hash = sha256_hex(b"");

            let mut canonical_headers = format!("content-length:0\nhost:{}\nx-amz-date:{}\n", host, amz_date);
            let mut signed_headers = "content-length;host;x-amz-date".to_string();
            if let Some(_) = session_token {
                canonical_headers.push_str(&format!("x-amz-security-token:{}\n", session_token.unwrap()));
                signed_headers.push_str(";x-amz-security-token");
            }

            let canonical_request = format!("{}\n{}\n\n{}\n{}\n{}", method, query, canonical_headers, signed_headers, payload_hash);
            let credential_scope = format!("{}/{}/{}/aws4_request", date_stamp, region, service);
            let string_to_sign = format!("AWS4-HMAC-SHA256\n{}\n{}\n{}", amz_date, credential_scope, sha256_hex(canonical_request.as_bytes()));

            let signing_key = get_signature_key(secret_key, &date_stamp, region, service);
            let signature = hmac_sha256_hex(&signing_key, string_to_sign.as_bytes());

            let auth_header = if let Some(_) = session_token {
                format!("AWS4-HMAC-SHA256 Credential={}/{},SignedHeaders={},Signature={}", access_key, credential_scope, signed_headers, signature)
            } else {
                format!("AWS4-HMAC-SHA256 Credential={}/{},SignedHeaders={},Signature={}", access_key, credential_scope, signed_headers, signature)
            };

            headers_vec.push(("authorization".to_string(), auth_header));
            if let Some(token) = session_token {
                headers_vec.push(("x-amz-security-token".to_string(), token.clone()));
                headers_vec.push(("x-amz-date".to_string(), amz_date));
            } else {
                headers_vec.push(("x-amz-date".to_string(), amz_date));
            }
            headers_vec.push(("content-length".to_string(), "0".to_string()));

        } else {
            // basic auth
            let encoded = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
            headers_vec.push(("authorization".to_string(), format!("Basic {}", encoded)));
        }
    }

    let mut body: Option<Vec<u8>> = None;
    if let Some(b) = matches.get_one::<String>("body-string") {
        body = Some(b.clone().into_bytes());
    } else if let Some(p) = matches.get_one::<String>("body-path") {
        match std::fs::read(p) {
            Ok(b) => body = Some(b),
            Err(e) => return Err(format!("{}", e)),
        }
    } else if let Some(p) = matches.get_one::<String>("body-lines") {
        match std::fs::read_to_string(p) {
            Ok(content) => {
                let lines: Vec<&str> = content.lines().collect();
                if !lines.is_empty() {
                    let mut rng = rand::thread_rng();
                    let idx = rng.gen_range(0..lines.len());
                    body = Some(lines[idx].as_bytes().to_vec());
                }
            },
            Err(e) => return Err(format!("{}", e)),
        }
    }

    let is_form = matches.contains_id("form");
    let mut boundary = String::new();
    if is_form {
        let mut rng = rand::thread_rng();
        let mut rand_bytes = [0u8;16];
        for i in 0..16 { rand_bytes[i]=rng.gen(); }
        let hex: String = rand_bytes.iter().map(|b| format!("{:02x}", b)).collect();
        boundary = format!("----formdata-oha-{}", hex);
        headers_vec.retain(|(k,_)| k.to_lowercase()!="content-type");
        headers_vec.push(("content-type".to_string(), format!("multipart/form-data; boundary={}", boundary)));
        let mut form_body: Vec<u8> = Vec::new();
        if let Some(forms) = matches.get_many::<String>("form") {
            for f in forms {
                if let Some((k,v)) = f.split_once('=') {
                    if v.starts_with('@') {
                        let path = &v[1..];
                        match std::fs::read(path) {
                            Ok(file_content) => {
                                let filename = std::path::Path::new(path).file_name().and_then(|s| s.to_str()).unwrap_or("file");
                                form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n", boundary, k, filename).as_bytes());
                                form_body.extend_from_slice(&file_content);
                                form_body.extend_from_slice(b"\r\n");
                            },
                            Err(e) => return Err(format!("{}", e)),
                        }
                    } else {
                        form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, k, v).as_bytes());
                    }
                }
            }
        }
        form_body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
        body = Some(form_body);
    }

    let method_for_debug = if is_form && method=="GET" { "POST" } else { method };

    let http_version_arg = matches.get_one::<String>("http-version").map(|s| s.as_str()).unwrap_or("1.1");
    let use_http2 = matches.get_flag("http2") || http_version_arg=="2";

    let uri_display = if use_http2 {
        url_str.to_string()
    } else {
        query.clone()
    };
    let version_display = if use_http2 {
        "HTTP/2.0"
    } else if http_version_arg=="1.0" {
        "HTTP/1.0"
    } else if http_version_arg=="0.9" {
        "HTTP/0.9"
    } else {
        "HTTP/1.1"
    };

    let disable_compression = matches.get_flag("disable-compression");

    let mut display_headers: BTreeMap<String,String> = BTreeMap::new();
    let mut has_accept = false;
    let mut has_user_agent = false;
    for (k,_) in &headers_vec {
        if k.to_lowercase()=="accept" { has_accept=true; }
        if k.to_lowercase()=="user-agent" { has_user_agent=true; }
    }
    if !has_accept {
        display_headers.insert("accept".to_string(), "*/*".to_string());
    }
    if !disable_compression {
        if !display_headers.contains_key("accept-encoding") && !headers_vec.iter().any(|(k,_)| k.to_lowercase()=="accept-encoding") {
            display_headers.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string());
        }
    }
    if !has_user_agent {
        display_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string());
    }
    for (k,v) in headers_vec.iter() {
        display_headers.insert(k.to_lowercase(), v.clone());
    }

    // Write Request
    {
        use std::io::Write;
        writeln!(out_buf, "Request {{").unwrap();
        writeln!(out_buf, "    method: {},", method_for_debug).unwrap();
        writeln!(out_buf, "    uri: {},", uri_display).unwrap();
        writeln!(out_buf, "    version: {},", version_display).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &display_headers {
            writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "    body: Full {{").unwrap();
        if let Some(b) = &body {
            let s = String::from_utf8_lossy(b);
            let escaped = s.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r");
            writeln!(out_buf, "        data: Some(").unwrap();
            writeln!(out_buf, "            b\"{}\",", escaped).unwrap();
            writeln!(out_buf, "        ),").unwrap();
        } else {
            writeln!(out_buf, "        data: None,").unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "}}").unwrap();
    }

    if use_http2 && parsed.scheme()!="https" {
        return Err("http2 error".to_string());
    }
    if http_version_arg=="0.9" {
        return Err("dispatch task is gone".to_string());
    }

    // Perform actual request (simplified)
    use std::net::{TcpStream, ToSocketAddrs};
    use std::io::{Read, Write};

    let mut target_host = host.clone();
    let mut target_port = port;
    if let Some(connect_tos) = matches.get_many::<String>("connect-to") {
        for ct in connect_tos {
            let parts: Vec<&str> = ct.split(':').collect();
            if parts.len()==4 {
                let orig_host = parts[0];
                let orig_port = parts[1].parse::<u16>().unwrap_or(0);
                let tgt_host = parts[2];
                let tgt_port = parts[3].parse::<u16>().unwrap_or(0);
                if orig_host==host && orig_port==port {
                    target_host = tgt_host.to_string();
                    target_port = tgt_port;
                }
            }
        }
    }

    // Resolve
    let addr_str = format!("{}:{}", target_host, target_port);
    let mut stream_opt: Option<TcpStream> = None;
    let mut last_err = String::new();
    for addr in addr_str.to_socket_addrs().map_err(|e| format!("{}", e))? {
        match TcpStream::connect_timeout(&addr, connect_timeout) {
            Ok(s) => { stream_opt=Some(s); break; },
            Err(e) => { last_err=format!("{}", e); }
        }
    }
    let mut stream = match stream_opt {
        Some(s) => s,
        None => return Err(last_err),
    };

    if let Some(to) = timeout_opt {
        stream.set_read_timeout(Some(to)).ok();
        stream.set_write_timeout(Some(to)).ok();
    }

    let mut request_str = format!("{} {} {}\r\n", method_for_debug, query, version_display);
    for (k,v) in &display_headers {
        request_str.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = &body {
        request_str.push_str(&format!("content-length: {}\r\n", b.len()));
    }
    request_str.push_str("\r\n");
    if let Err(e) = stream.write_all(request_str.as_bytes()) {
        return Err(format!("{}", e));
    }
    if let Some(b) = &body {
        if let Err(e) = stream.write_all(b) {
            return Err(format!("{}", e));
        }
    }

    let mut resp_buf = Vec::new();
    let mut tmp = [0u8;4096];
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => resp_buf.extend_from_slice(&tmp[..n]),
            Err(e) => {
                if e.kind()==std::io::ErrorKind::TimedOut || e.kind()==std::io::ErrorKind::WouldBlock {
                    return Err("timeout".to_string());
                }
                return Err(format!("{}", e));
            }
        }
    }

    let resp_str = String::from_utf8_lossy(&resp_buf);
    let mut lines = resp_str.lines();
    let status_line = lines.next().unwrap_or("");
    let mut status_code = 200;
    let mut version_resp = "HTTP/1.1";
    if status_line.starts_with("HTTP/") {
        let parts: Vec<&str> = status_line.split_whitespace().collect();
        if parts.len()>=2 {
            version_resp = parts[0];
            status_code = parts[1].parse().unwrap_or(200);
        }
    }
    let mut resp_headers: BTreeMap<String,String> = BTreeMap::new();
    let mut body_start = 0;
    if let Some(pos) = resp_str.find("\r\n\r\n") {
        body_start = pos+4;
        let header_part = &resp_str[..pos];
        for (i,line) in header_part.split("\r\n").enumerate() {
            if i==0 { continue; }
            if let Some((k,v)) = line.split_once(':') {
                resp_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
            }
        }
    }
    let body_bytes = if body_start < resp_buf.len() { &resp_buf[body_start..] } else { b"" };

    {
        use std::io::Write;
        writeln!(out_buf, "\nResponse {{").unwrap();
        writeln!(out_buf, "    status: {},", status_code).unwrap();
        writeln!(out_buf, "    version: {},", version_resp).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &resp_headers {
            writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        let body_str = String::from_utf8_lossy(body_bytes);
        let escaped = body_str.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r");
        writeln!(out_buf, "    body: b\"{}\",", escaped).unwrap();
        writeln!(out_buf, "}}").unwrap();
    }

    Ok(())
}

fn do_single_request(
    url_str: &str,
    method: &str,
    headers_raw: &[String],
    _proxy_headers_raw: &[String],
    connect_to_raw: &[String],
    host_override: Option<&str>,
    basic_auth: Option<&str>,
    _aws_session: Option<&str>,
    _aws_sigv4: Option<&str>,
    accept_header: Option<&str>,
    content_type: Option<&str>,
    body_string: Option<&str>,
    body_from_file: Option<&[u8]>,
    body_lines: Option<&[Vec<u8>]>,
    forms: &[String],
    proxy: Option<&str>,
    disable_keepalive: bool,
    disable_compression: bool,
    redirect_limit: usize,
    timeout_opt: Option<Duration>,
    connect_timeout: Duration,
    kept_stream: &mut Option<std::net::TcpStream>,
    kept_host: &mut String,
    kept_port: &mut u16,
) -> Result<(u16, usize, Option<f64>, Option<f64>, f64), (String, Option<f64>, Option<f64>)> {
