    let url_arg = matches.get_one::<String>("URL").unwrap().clone();
    let urls_from_file = matches.get_flag("urls-from-file");
    let rand_regex = matches.get_flag("rand-regex-url");
    let latency_correction = matches.get_flag("latency-correction");
    let stats_breakdown = matches.get_flag("stats-success-breakdown");
    let disable_keepalive = matches.get_flag("disable-keepalive");
    let disable_compression = matches.get_flag("disable-compression");
    let method = matches.get_one::<String>("method").unwrap().clone();
    let output_path = matches.get_one::<String>("output").cloned();
    let time_unit = matches.get_one::<String>("time-unit").cloned();
    let db_url = matches.get_one::<String>("db-url").cloned();
    let host_override = matches.get_one::<String>("host").cloned();
    let basic_auth = matches.get_one::<String>("basic-auth").cloned();
    let accept_header = matches.get_one::<String>("accept").cloned();
    let content_type = matches.get_one::<String>("content-type").cloned();
    let body_string = matches.get_one::<String>("body-string").cloned();
    let body_path = matches.get_one::<String>("body-path").cloned();
    let body_lines_path = matches.get_one::<String>("body-lines").cloned();
    let forms: Vec<String> = matches.get_many::<String>("form").map(|v| v.cloned().collect()).unwrap_or_default();
    let headers_raw: Vec<String> = matches.get_many::<String>("headers").map(|v| v.cloned().collect()).unwrap_or_default();
    let connect_to_raw: Vec<String> = matches.get_many::<String>("connect-to").map(|v| v.cloned().collect()).unwrap_or_default();
    let wait_ongoing = matches.get_flag("wait");

    let mut url_list: Vec<String> = Vec::new();
    if urls_from_file {
        match std::fs::read_to_string(&url_arg) {
            Ok(content) => {
                for line in content.lines() {
                    let trimmed = line.trim();
                    if !trimmed.is_empty() {
                        url_list.push(trimmed.to_string());
                    }
                }
                if url_list.is_empty() {
