                }
            },
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        url_list.push(url_arg.clone());
    }

    let body_from_file: Option<Vec<u8>> = if let Some(p) = body_path {
        match std::fs::read(&p) {
            Ok(b) => Some(b),
            Err(e) => {
                eprintln!("Error: {}", e);
