fn parse_n_requests(s: &str) -> Result<u64, String> {
    if s.is_empty() {
        return Err("invalid digit found in string".to_string());
    }
    let lower = s.to_lowercase();
    let (num_part, mult) = if lower.ends_with('k') {
        (&s[..s.len()-1], 1000)
    } else if lower.ends_with('m') {
        (&s[..s.len()-1], 1_000_000)
    } else {
        (s, 1)
    };
    if num_part.is_empty() {
        return Err("invalid digit found in string".to_string());
    }
    match num_part.parse::<u64>() {
        Ok(v) => Ok(v * mult),
        Err(_) => Err("invalid digit found in string".to_string()),
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }
    let mut num_end = 0;
    let mut has_digit = false;
    let mut has_dot = false;
    for (i,c) in s.char_indices() {
        if c.is_ascii_digit() {
            has_digit = true;
            num_end = i + c.len_utf8();
        } else if c=='.' {
            if has_dot { break; }
            has_dot = true;
            num_end = i + c.len_utf8();
        } else {
            break;
        }
    }
    if !has_digit || num_end==0 {
        return Err("expected number at 0".to_string());
    }
    let num_str = &s[..num_end];
    let unit_str = s[num_end..].trim();
    if unit_str.is_empty() {
        return Err("time unit needed, for example 10sec or 10ms".to_string());
    }
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let mult = match unit_str {
        "ns" => 1e-9,
        "us" | "µs" | "μs" => 1e-6,
        "ms" | "milli" | "millis" | "msec" | "msecs" | "millisecond" | "milliseconds" => 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => 1.0,
        "m" | "min" | "mins" | "minute" | "minutes" => 60.0,
        "h" | "hour" | "hours" => 3600.0,
        "d" | "day" | "days" => 86400.0,
        "w" | "week" | "weeks" => 604800.0,
        "month" | "months" => 2629746.0,
        "y" | "year" | "years" => 31556952.0,
        _ => {
            return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit_str));
        }
    };
    Ok(Duration::from_secs_f64(num * mult))
}

fn generate_rand_url(pattern: &str, max_repeat: usize) -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut out = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c == '[' {
            let mut j = i+1;
            while j < chars.len() && chars[j] != ']' {
                j+=1;
            }
            if j>=chars.len() {
                out.push(c);
                i+=1;
                continue;
            }
            let inner: String = chars[i+1..j].iter().collect();
            let mut candidates: Vec<char> = Vec::new();
            let inner_chars: Vec<char> = inner.chars().collect();
            let mut k = 0;
            while k < inner_chars.len() {
                let ch = inner_chars[k];
                if k+2 < inner_chars.len() && inner_chars[k+1]=='-' {
                    let start = ch;
                    let end = inner_chars[k+2];
                    if start <= end {
                        for rc in (start as u8)..=(end as u8) {
                            candidates.push(rc as char);
                        }
                    }
                    k+=3;
                } else {
                    candidates.push(ch);
                    k+=1;
                }
            }
            if candidates.is_empty() {
                candidates.push('a');
            }
            let mut repeat = 1;
            let mut quant = ' ';
            if j+1 < chars.len() {
                let next = chars[j+1];
                if next=='*' || next=='+' || next=='?' {
                    quant = next;
                } else if next=='{' {
                    let mut end_brace = j+2;
                    while end_brace < chars.len() && chars[end_brace]!='}' {
                        end_brace+=1;
                    }
                    if end_brace < chars.len() {
                        let brace_content: String = chars[j+2..end_brace].iter().collect();
                        if let Ok(n) = brace_content.split(',').next().unwrap_or("1").trim().parse::<usize>() {
                            repeat = n;
                        }
                        j = end_brace;
                    }
                }
            }
            if quant=='*' {
                repeat = rng.gen_range(0..=max_repeat);
                j+=1;
            } else if quant=='+' {
                repeat = 1 + rng.gen_range(0..=max_repeat);
                j+=1;
            } else if quant=='?' {
                repeat = if rng.gen_bool(0.5) {1} else {0};
                j+=1;
            }

            for _ in 0..repeat {
                let idx = rng.gen_range(0..candidates.len());
                out.push(candidates[idx]);
            }

            i = j+1;
        } else if c == '.' {
            out.push('.');
            i+=1;
        } else {
            out.push(c);
            i+=1;
        }
    }
    out
}

fn do_debug_request(matches: &clap::ArgMatches, url_str: &str, out_buf: &mut Vec<u8>, connect_timeout: Duration, timeout_opt: Option<Duration>, _burst_delay: Option<Duration>, _qps: Option<f64>, _redirect_limit: usize, _max_repeat: usize) -> Result<(), String> {
    let parsed = match url::Url::parse(url_str) {
        Ok(u) => u,
        Err(_) => return Err(format!("relative URL without a base")),
    };
    let host = parsed.host_str().ok_or("no host")?.to_string();
    let port = parsed.port_or_known_default().unwrap_or(80);
    let path = if parsed.path().is_empty() { "/" } else { parsed.path() };
    let query = if let Some(q) = parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };
    let method = matches.get_one::<String>("method").map(|s| s.as_str()).unwrap_or("GET");
    let mut headers_vec: Vec<(String,String)> = Vec::new();
    if let Some(hs) = matches.get_many::<String>("headers") {
        for h in hs {
            if let Some((k,v)) = h.split_once(':') {
                headers_vec.push((k.trim().to_string(), v.trim().to_string()));
            }
        }
    }
    if let Some(a) = matches.get_one::<String>("accept") {
        headers_vec.push(("accept".to_string(), a.clone()));
    }
    if let Some(ct) = matches.get_one::<String>("content-type") {
        headers_vec.push(("content-type".to_string(), ct.clone()));
    }
    if let Some(h) = matches.get_one::<String>("host") {
        headers_vec.push(("host".to_string(), h.clone()));
    } else {
        headers_vec.push(("host".to_string(), format!("{}:{}", host, port)));
    }
    if let Some(auth) = matches.get_one::<String>("basic-auth") {
        if matches.contains_id("aws-sigv4") {
            let sigv4_str = matches.get_one::<String>("aws-sigv4").unwrap();
            let parts: Vec<&str> = sigv4_str.split(':').collect();
            if parts.len()!=4 {
                return Err("invalid aws-sigv4 format".to_string());
            }
            let region = parts[2];
            let service = parts[3];
            let access_key = auth.split(':').next().unwrap_or("");
            let secret_key = auth.split(':').nth(1).unwrap_or("");
            let session_token = matches.get_one::<String>("aws-session").map(|s| s.as_str());
            let amz_date = "20260908T110723Z".to_string();
            let date_stamp = "20260908".to_string();
            let payload_hash = sha256_hex(b"");
            let mut canonical_headers = format!("content-length:0\nhost:{}\nx-amz-date:{}\n", host, amz_date);
            let mut signed_headers = "content-length;host;x-amz-date".to_string();
            if let Some(_) = session_token {
                canonical_headers.push_str(&format!("x-amz-security-token:{}\n", session_token.unwrap()));
                signed_headers.push_str(";x-amz-security-token");
            }
            let canonical_request = format!("{}\n{}\n\n{}\n{}\n{}", method, query, canonical_headers, signed_headers, payload_hash);
            let credential_scope = format!("{}/{}/{}/aws4_request", date_stamp, region, service);
            let string_to_sign = format!("AWS4-HMAC-SHA256\n{}\n{}\n{}", amz_date, credential_scope, sha256_hex(canonical_request.as_bytes()));
            let signing_key = get_signature_key(secret_key, &date_stamp, region, service);
            let signature = hmac_sha256_hex(&signing_key, string_to_sign.as_bytes());
            let auth_header = format!("AWS4-HMAC-SHA256 Credential={}/{},SignedHeaders={},Signature={}", access_key, credential_scope, signed_headers, signature);
            headers_vec.push(("authorization".to_string(), auth_header));
            if let Some(token) = session_token {
                headers_vec.push(("x-amz-security-token".to_string(), token.clone()));
                headers_vec.push(("x-amz-date".to_string(), amz_date));
            } else {
                headers_vec.push(("x-amz-date".to_string(), amz_date));
            }
            headers_vec.push(("content-length".to_string(), "0".to_string()));
        } else {
            let encoded = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
            headers_vec.push(("authorization".to_string(), format!("Basic {}", encoded)));
        }
    }

    let mut body: Option<Vec<u8>> = None;
    if let Some(b) = matches.get_one::<String>("body-string") {
        body = Some(b.clone().into_bytes());
    } else if let Some(p) = matches.get_one::<String>("body-path") {
        match std::fs::read(p) {
            Ok(b) => body = Some(b),
            Err(e) => return Err(format!("{}", e)),
        }
    } else if let Some(p) = matches.get_one::<String>("body-lines") {
        match std::fs::read_to_string(p) {
            Ok(content) => {
                let lines: Vec<&str> = content.lines().collect();
                if !lines.is_empty() {
                    let mut rng = rand::thread_rng();
                    let idx = rng.gen_range(0..lines.len());
                    body = Some(lines[idx].as_bytes().to_vec());
                }
            },
            Err(e) => return Err(format!("{}", e)),
        }
    }

    let is_form = matches.contains_id("form");
    let mut boundary = String::new();
    if is_form {
        let mut rng = rand::thread_rng();
        let mut rand_bytes = [0u8;16];
        for i in 0..16 { rand_bytes[i]=rng.gen(); }
        let hex: String = rand_bytes.iter().map(|b| format!("{:02x}", b)).collect();
        boundary = format!("----formdata-oha-{}", hex);
        headers_vec.retain(|(k,_)| k.to_lowercase()!="content-type");
        headers_vec.push(("content-type".to_string(), format!("multipart/form-data; boundary={}", boundary)));
        let mut form_body: Vec<u8> = Vec::new();
        if let Some(forms) = matches.get_many::<String>("form") {
            for f in forms {
                if let Some((k,v)) = f.split_once('=') {
                    if v.starts_with('@') {
                        let path = &v[1..];
                        match std::fs::read(path) {
                            Ok(file_content) => {
                                let filename = std::path::Path::new(path).file_name().and_then(|s| s.to_str()).unwrap_or("file");
                                form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n", boundary, k, filename).as_bytes());
                                form_body.extend_from_slice(&file_content);
                                form_body.extend_from_slice(b"\r\n");
                            },
                            Err(e) => return Err(format!("{}", e)),
                        }
                    } else {
                        form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, k, v).as_bytes());
                    }
                }
            }
        }
        form_body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
        body = Some(form_body);
    }

    let method_for_debug = if is_form && method=="GET" { "POST" } else { method };

    let http_version_arg = matches.get_one::<String>("http-version").map(|s| s.as_str()).unwrap_or("1.1");
    let use_http2 = matches.get_flag("http2") || http_version_arg=="2";

    let uri_display = if use_http2 {
        url_str.to_string()
    } else {
        query.clone()
    };
    let version_display = if use_http2 {
        "HTTP/2.0"
    } else if http_version_arg=="1.0" {
        "HTTP/1.0"
    } else if http_version_arg=="0.9" {
        "HTTP/0.9"
    } else {
        "HTTP/1.1"
    };

    let disable_compression = matches.get_flag("disable-compression");

    let mut display_headers: BTreeMap<String,String> = BTreeMap::new();
    let mut has_accept = false;
    let mut has_user_agent = false;
    for (k,_) in &headers_vec {
        if k.to_lowercase()=="accept" { has_accept=true; }
        if k.to_lowercase()=="user-agent" { has_user_agent=true; }
    }
    if !has_accept {
        display_headers.insert("accept".to_string(), "*/*".to_string());
    }
    if !disable_compression {
        if !display_headers.contains_key("accept-encoding") && !headers_vec.iter().any(|(k,_)| k.to_lowercase()=="accept-encoding") {
            display_headers.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string());
        }
    }
    if !has_user_agent {
        display_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string());
    }
    for (k,v) in headers_vec.iter() {
        display_headers.insert(k.to_lowercase(), v.clone());
    }

    {
        use std::io::Write;
        writeln!(out_buf, "Request {{").unwrap();
        writeln!(out_buf, "    method: {},", method_for_debug).unwrap();
        writeln!(out_buf, "    uri: {},", uri_display).unwrap();
        writeln!(out_buf, "    version: {},", version_display).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &display_headers {
            writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "    body: Full {{").unwrap();
        if let Some(b) = &body {
            let s = String::from_utf8_lossy(b);
            let escaped = s.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r");
            writeln!(out_buf, "        data: Some(").unwrap();
            writeln!(out_buf, "            b\"{}\",", escaped).unwrap();
            writeln!(out_buf, "        ),").unwrap();
        } else {
            writeln!(out_buf, "        data: None,").unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "}}").unwrap();
    }

    if use_http2 && parsed.scheme()!="https" {
        return Err("http2 error".to_string());
    }
    if http_version_arg=="0.9" {
        return Err("dispatch task is gone".to_string());
    }

    use std::net::{TcpStream, ToSocketAddrs};
    use std::io::{Read, Write};

    let mut target_host = host.clone();
    let mut target_port = port;
    if let Some(connect_tos) = matches.get_many::<String>("connect-to") {
        for ct in connect_tos {
            let parts: Vec<&str> = ct.split(':').collect();
            if parts.len()==4 {
                let orig_host = parts[0];
                let orig_port = parts[1].parse::<u16>().unwrap_or(0);
                let tgt_host = parts[2];
                let tgt_port = parts[3].parse::<u16>().unwrap_or(0);
                if orig_host==host && orig_port==port {
                    target_host = tgt_host.to_string();
                    target_port = tgt_port;
                }
            }
        }
    }

    let addr_str = format!("{}:{}", target_host, target_port);
    let mut stream_opt: Option<TcpStream> = None;
    let mut last_err = String::new();
    for addr in addr_str.to_socket_addrs().map_err(|e| format!("{}", e))? {
        match TcpStream::connect_timeout(&addr, connect_timeout) {
            Ok(s) => { stream_opt=Some(s); break; },
            Err(e) => { last_err=format!("{}", e); }
        }
    }
    let mut stream = match stream_opt {
        Some(s) => s,
        None => return Err(last_err),
    };

    if let Some(to) = timeout_opt {
        stream.set_read_timeout(Some(to)).ok();
        stream.set_write_timeout(Some(to)).ok();
    }

    let mut request_str = format!("{} {} {}\r\n", method_for_debug, query, version_display);
    for (k,v) in &display_headers {
        request_str.push_str(&format!("{}: {}\r\n", k, v));
    }
    if let Some(b) = &body {
        request_str.push_str(&format!("content-length: {}\r\n", b.len()));
    }
    request_str.push_str("\r\n");
    if let Err(e) = stream.write_all(request_str.as_bytes()) {
        return Err(format!("{}", e));
    }
    if let Some(b) = &body {
        if let Err(e) = stream.write_all(b) {
            return Err(format!("{}", e));
        }
    }

    let mut resp_buf = Vec::new();
    let mut tmp = [0u8;4096];
    loop {
        match stream.read(&mut tmp) {
            Ok(0) => break,
            Ok(n) => resp_buf.extend_from_slice(&tmp[..n]),
            Err(e) => {
                if e.kind()==std::io::ErrorKind::TimedOut || e.kind()==std::io::ErrorKind::WouldBlock {
                    return Err("timeout".to_string());
                }
                return Err(format!("{}", e));
            }
        }
    }

    let resp_str = String::from_utf8_lossy(&resp_buf);
    let mut lines = resp_str.lines();
    let status_line = lines.next().unwrap_or("");
    let mut status_code = 200;
    let mut version_resp = "HTTP/1.1";
    if status_line.starts_with("HTTP/") {
        let parts: Vec<&str> = status_line.split_whitespace().collect();
        if parts.len()>=2 {
            version_resp = parts[0];
            status_code = parts[1].parse().unwrap_or(200);
        }
    }
    let mut resp_headers: BTreeMap<String,String> = BTreeMap::new();
    let mut body_start = 0;
    if let Some(pos) = resp_str.find("\r\n\r\n") {
        body_start = pos+4;
        let header_part = &resp_str[..pos];
        for (i,line) in header_part.split("\r\n").enumerate() {
            if i==0 { continue; }
            if let Some((k,v)) = line.split_once(':') {
                resp_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
            }
        }
    }
    let body_bytes = if body_start < resp_buf.len() { &resp_buf[body_start..] } else { b"" };

    {
        use std::io::Write;
        writeln!(out_buf, "\nResponse {{").unwrap();
        writeln!(out_buf, "    status: {},", status_code).unwrap();
        writeln!(out_buf, "    version: {},", version_resp).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &resp_headers {
            writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        let body_str = String::from_utf8_lossy(body_bytes);
        let escaped = body_str.replace('\\', "\\\\").replace('"', "\\\"").replace('\n', "\\n").replace('\r', "\\r");
        writeln!(out_buf, "    body: b\"{}\",", escaped).unwrap();
        writeln!(out_buf, "}}").unwrap();
    }

    Ok(())
}

fn do_single_request(
    url_str: &str,
    method: &str,
    headers_raw: &[String],
    connect_to_raw: &[String],
    host_override: Option<&str>,
    basic_auth: Option<&str>,
    accept_header: Option<&str>,
    content_type: Option<&str>,
    body_string: Option<&str>,
    body_from_file: Option<&[u8]>,
    body_lines: Option<&[Vec<u8>]>,
    forms: &[String],
    disable_keepalive: bool,
    disable_compression: bool,
    redirect_limit: usize,
    timeout_opt: Option<Duration>,
    connect_timeout: Duration,
    kept_stream: &mut Option<std::net::TcpStream>,
    kept_host: &mut String,
    kept_port: &mut u16,
) -> Result<(u16, usize, Option<f64>, Option<f64>, f64), (String, Option<f64>, Option<f64>)> {
    let mut current_url = url_str.to_string();
    let mut current_parsed = match url::Url::parse(&current_url) {
        Ok(u) => u,
        Err(_) => return Err(("relative URL without a base".to_string(), None, None)),
    };
    let mut redirects = 0;
    loop {
        let host = current_parsed.host_str().unwrap_or("").to_string();
        let port = current_parsed.port_or_known_default().unwrap_or(80);
        let path = if current_parsed.path().is_empty() { "/" } else { current_parsed.path() };
        let query = if let Some(q) = current_parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };

        let dns_start = Instant::now();
        let target_host = host.clone();
        use std::net::ToSocketAddrs;
        let addr_str = format!("{}:{}", target_host, port);
        let dns_lookup_duration;
        let addrs: Vec<std::net::SocketAddr> = match addr_str.to_socket_addrs() {
            Ok(iter) => {
                dns_lookup_duration = dns_start.elapsed().as_secs_f64();
                iter.collect()
            },
            Err(e) => {
                return Err((format!("{}", e), Some(dns_start.elapsed().as_secs_f64()), None));
            }
        };

        let dialup_start = Instant::now();
        let mut stream_opt = None;
        let mut last_err = String::new();
        for addr in &addrs {
            match std::net::TcpStream::connect_timeout(addr, connect_timeout) {
                Ok(s) => { stream_opt=Some(s); break; },
                Err(e) => { last_err=format!("{}", e); }
            }
        }
        let mut stream = match stream_opt {
            Some(s) => s,
            None => {
                return Err((last_err, Some(dns_lookup_duration), None));
            }
        };
        let dns_dialup_duration = dialup_start.elapsed().as_secs_f64() + dns_lookup_duration;
        let response_delay_start = Instant::now();

        if let Some(to) = timeout_opt {
            stream.set_read_timeout(Some(to)).ok();
            stream.set_write_timeout(Some(to)).ok();
        }

        let mut display_headers: BTreeMap<String,String> = BTreeMap::new();
        if let Some(a) = accept_header {
            display_headers.insert("accept".to_string(), a.to_string());
        } else {
            display_headers.insert("accept".to_string(), "*/*".to_string());
        }
        if !disable_compression {
            display_headers.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string());
        }
        display_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string());
        if let Some(h) = host_override {
            display_headers.insert("host".to_string(), h.to_string());
        } else {
            display_headers.insert("host".to_string(), format!("{}:{}", host, port));
        }
        for h in headers_raw {
            if let Some((k,v)) = h.split_once(':') {
                display_headers.insert(k.trim().to_lowercase(), v.trim().to_string());
            }
        }
        if let Some(auth) = basic_auth {
            let encoded = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
            display_headers.insert("authorization".to_string(), format!("Basic {}", encoded));
        }
        if let Some(ct) = content_type {
            display_headers.insert("content-type".to_string(), ct.to_string());
        }

        let mut body_bytes: Option<Vec<u8>> = None;
        if let Some(s) = body_string {
            body_bytes = Some(s.as_bytes().to_vec());
        } else if let Some(b) = body_from_file {
            body_bytes = Some(b.to_vec());
        } else if let Some(lines) = body_lines {
            if !lines.is_empty() {
                let mut rng = rand::thread_rng();
                let idx = rng.gen_range(0..lines.len());
                body_bytes = Some(lines[idx].clone());
            }
        } else if !forms.is_empty() {
            let mut rng = rand::thread_rng();
            let mut rand_bytes = [0u8;16];
            for i in 0..16 { rand_bytes[i]=rng.gen(); }
            let hex: String = rand_bytes.iter().map(|b| format!("{:02x}", b)).collect();
            let boundary = format!("----formdata-oha-{}", hex);
            display_headers.insert("content-type".to_string(), format!("multipart/form-data; boundary={}", boundary));
            let mut form_body: Vec<u8> = Vec::new();
            for f in forms {
                if let Some((k,v)) = f.split_once('=') {
                    if v.starts_with('@') {
                        let path = &v[1..];
                        if let Ok(file_content) = std::fs::read(path) {
                            let filename = std::path::Path::new(path).file_name().and_then(|s| s.to_str()).unwrap_or("file");
                            form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n", boundary, k, filename).as_bytes());
                            form_body.extend_from_slice(&file_content);
                            form_body.extend_from_slice(b"\r\n");
                        }
                    } else {
                        form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, k, v).as_bytes());
                    }
                }
            }
            form_body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
            body_bytes = Some(form_body);
        }

        let method_for_req = if !forms.is_empty() && method=="GET" { "POST" } else { method };

        let mut request_str = format!("{} {} HTTP/1.1\r\n", method_for_req, query);
        for (k,v) in &display_headers {
            request_str.push_str(&format!("{}: {}\r\n", k, v));
        }
        if let Some(b) = &body_bytes {
            request_str.push_str(&format!("content-length: {}\r\n", b.len()));
        }
        request_str.push_str("\r\n");

        use std::io::{Read, Write};
        if let Err(e) = stream.write_all(request_str.as_bytes()) {
            return Err((format!("{}", e), Some(dns_lookup_duration), Some(dns_dialup_duration)));
        }
        if let Some(b) = &body_bytes {
            if let Err(e) = stream.write_all(b) {
                return Err((format!("{}", e), Some(dns_lookup_duration), Some(dns_dialup_duration)));
            }
        }

        let mut resp_buf = Vec::new();
        let mut tmp = [0u8;4096];
        let mut response_delay = 0.0;
        let mut first_byte = true;
        loop {
            match stream.read(&mut tmp) {
                Ok(0) => break,
                Ok(n) => {
                    if first_byte {
                        response_delay = response_delay_start.elapsed().as_secs_f64();
                        first_byte = false;
                    }
                    resp_buf.extend_from_slice(&tmp[..n]);
                    if let Some(pos) = resp_buf.windows(4).position(|w| w==b"\r\n\r\n") {
                        let header_str = String::from_utf8_lossy(&resp_buf[..pos]);
                        let mut content_len: Option<usize> = None;
                        for line in header_str.lines().skip(1) {
                            if let Some((k,v)) = line.split_once(':') {
                                if k.trim().to_lowercase()=="content-length" {
                                    content_len = v.trim().parse().ok();
                                }
                            }
                        }
                        if let Some(cl) = content_len {
                            if resp_buf.len() >= pos+4+cl {
                                break;
                            }
                        }
                    }
                },
                Err(e) => {
                    if e.kind()==std::io::ErrorKind::TimedOut || e.kind()==std::io::ErrorKind::WouldBlock {
                        return Err((format!("timeout"), Some(dns_lookup_duration), Some(dns_dialup_duration)));
                    }
                    return Err((format!("{}", e), Some(dns_lookup_duration), Some(dns_dialup_duration)));
                }
            }
        }

        let resp_str = String::from_utf8_lossy(&resp_buf);
        let mut status_code = 200;
        let mut location: Option<String> = None;
        let mut lines = resp_str.lines();
        if let Some(status_line) = lines.next() {
            if status_line.starts_with("HTTP/") {
                let parts: Vec<&str> = status_line.split_whitespace().collect();
                if parts.len()>=2 {
                    status_code = parts[1].parse().unwrap_or(200);
                }
            }
        }
        for line in resp_str.split("\r\n").skip(1) {
            if line.is_empty() { break; }
            if let Some((k,v)) = line.split_once(':') {
                if k.trim().to_lowercase()=="location" {
                    location = Some(v.trim().to_string());
                }
            }
        }

        if status_code>=300 && status_code<400 && redirect_limit>0 {
            if let Some(loc) = location {
                if redirects < redirect_limit {
                    let next_url = match url::Url::parse(&loc) {
                        Ok(u) => u.to_string(),
                        Err(_) => {
                            if let Ok(base) = url::Url::parse(&current_url) {
                                if let Ok(joined) = base.join(&loc) {
                                    joined.to_string()
                                } else {
                                    loc.clone()
                                }
                            } else {
                                loc.clone()
                            }
                        }
                    };
                    current_url = next_url;
                    current_parsed = match url::Url::parse(&current_url) {
                        Ok(u) => u,
                        Err(_) => current_parsed.clone(),
                    };
                    redirects+=1;
                    continue;
                } else {
                    return Err((format!("Redirection limit has reached"), Some(dns_lookup_duration), Some(dns_dialup_duration)));
                }
            }
        }

        let body_start = if let Some(pos) = resp_buf.windows(4).position(|w| w==b"\r\n\r\n") { pos+4 } else { resp_buf.len() };
        let body_len = resp_buf.len() - body_start;

        if !disable_keepalive {
            if kept_host.is_empty() || *kept_host==host && *kept_port==port {
                *kept_stream = Some(stream);
                *kept_host = host;
                *kept_port = port;
            }
        }

        return Ok((status_code as u16, body_len, Some(dns_lookup_duration), Some(dns_dialup_duration), response_delay));
    }
}

fn convert_time(secs: f64, unit: &str) -> f64 {
    match unit {
        "ns" => secs * 1e9,
        "us" => secs * 1e6,
        "ms" => secs * 1e3,
        "s" => secs,
        "m" => secs / 60.0,
        "h" => secs / 3600.0,
        _ => secs,
    }
}

fn format_time(secs: f64, unit: &str) -> String {
    if secs.is_nan() {
        return format!("NaN {}", unit);
    }
    if secs.is_infinite() {
        if secs.is_sign_negative() {
            return format!("-inf {}", unit);
        } else {
            return format!("inf {}", unit);
        }
    }
    format!("{:.4} {}", convert_time(secs, unit), unit)
}

fn format_time_auto(secs: f64) -> String {
    if secs.is_nan() {
        return "NaN ns".to_string();
    }
    if secs.is_infinite() {
        if secs.is_sign_negative() {
            return "-inf ns".to_string();
        } else {
            return "inf ns".to_string();
        }
    }
    if secs < 0.000001 {
        format!("{:.4} ns", secs*1e9)
    } else if secs < 0.001 {
        format!("{:.4} us", secs*1e6)
    } else if secs < 1.0 {
        format!("{:.4} ms", secs*1e3)
    } else {
        format!("{:.4} sec", secs)
    }
}

fn format_data_rate(bps: f64) -> String {
    if bps < 1024.0 {
        format!("{} B", bps as usize)
    } else if bps < 1024.0*1024.0 {
        format!("{:.2} KiB", bps/1024.0)
    } else {
        format!("{:.2} MiB", bps/(1024.0*1024.0))
    }
}

fn sha256(data: &[u8]) -> [u8;32] {
    const K: [u32; 64] = [
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2,
    ];
    let mut h: [u32;8] = [
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    ];

    let mut data = data.to_vec();
    let bit_len = (data.len() as u64)*8;
    data.push(0x80);
    while (data.len() % 64) != 56 {
        data.push(0);
    }
    data.extend_from_slice(&bit_len.to_be_bytes());

    for chunk in data.chunks(64) {
        let mut w = [0u32;64];
        for i in 0..16 {
            w[i] = u32::from_be_bytes([chunk[i*4],chunk[i*4+1],chunk[i*4+2],chunk[i*4+3]]);
        }
        for i in 16..64 {
            let s0 = w[i-15].rotate_right(7) ^ w[i-15].rotate_right(18) ^ (w[i-15]>>3);
            let s1 = w[i-2].rotate_right(17) ^ w[i-2].rotate_right(19) ^ (w[i-2]>>10);
            w[i] = w[i-16].wrapping_add(s0).wrapping_add(w[i-7]).wrapping_add(s1);
        }
        let mut a=h[0]; let mut b=h[1]; let mut c=h[2]; let mut d=h[3];
        let mut e=h[4]; let mut f=h[5]; let mut g=h[6]; let mut h0=h[7];
        for i in 0..64 {
            let s1 = e.rotate_right(6) ^ e.rotate_right(11) ^ e.rotate_right(25);
            let ch = (e & f) ^ ((!e) & g);
            let temp1 = h0.wrapping_add(s1).wrapping_add(ch).wrapping_add(K[i]).wrapping_add(w[i]);
            let s0 = a.rotate_right(2) ^ a.rotate_right(13) ^ a.rotate_right(22);
            let maj = (a & b) ^ (a & c) ^ (b & c);
            let temp2 = s0.wrapping_add(maj);
            h0=g; g=f; f=e; e=d.wrapping_add(temp1); d=c; c=b; b=a; a=temp1.wrapping_add(temp2);
        }
        h[0]=h[0].wrapping_add(a); h[1]=h[1].wrapping_add(b); h[2]=h[2].wrapping_add(c); h[3]=h[3].wrapping_add(d);
        h[4]=h[4].wrapping_add(e); h[5]=h[5].wrapping_add(f); h[6]=h[6].wrapping_add(g); h[7]=h[7].wrapping_add(h0);
    }

    let mut out = [0u8;32];
    for i in 0..8 {
        out[i*4..i*4+4].copy_from_slice(&h[i].to_be_bytes());
    }
    out
}

fn sha256_hex(data: &[u8]) -> String {
    let hash = sha256(data);
    hash.iter().map(|b| format!("{:02x}", b)).collect()
}

fn hmac_sha256(key: &[u8], data: &[u8]) -> Vec<u8> {
    const BLOCK_SIZE: usize = 64;
    let mut key_block = vec![0u8; BLOCK_SIZE];
    if key.len() > BLOCK_SIZE {
        let hashed = sha256(key);
        key_block[..32].copy_from_slice(&hashed);
    } else {
        key_block[..key.len()].copy_from_slice(key);
    }
    let mut o_key_pad = vec![0u8; BLOCK_SIZE];
    let mut i_key_pad = vec![0u8; BLOCK_SIZE];
    for i in 0..BLOCK_SIZE {
        o_key_pad[i] = key_block[i] ^ 0x5c;
        i_key_pad[i] = key_block[i] ^ 0x36;
    }
    let mut inner = i_key_pad;
    inner.extend_from_slice(data);
    let inner_hash = sha256(&inner);
    let mut outer = o_key_pad;
    outer.extend_from_slice(&inner_hash);
    sha256(&outer).to_vec()
}

fn hmac_sha256_hex(key: &[u8], data: &[u8]) -> String {
    let mac = hmac_sha256(key, data);
    mac.iter().map(|b| format!("{:02x}", b)).collect()
}

fn get_signature_key(secret: &str, date: &str, region: &str, service: &str) -> Vec<u8> {
    let k_secret = format!("AWS4{}", secret);
    let k_date = hmac_sha256(k_secret.as_bytes(), date.as_bytes());
    let k_region = hmac_sha256(&k_date, region.as_bytes());
    let k_service = hmac_sha256(&k_region, service.as_bytes());
    let k_signing = hmac_sha256(&k_service, b"aws4_request");
    k_signing
}
