                    rx.recv().ok()
                };
                let job_idx = match job_idx_opt {
                    Some(Some(idx)) => idx,
                    Some(None) => break,
                    None => break,
                };

                if let Some(dur) = duration_opt {
                    if start_instant.elapsed() >= dur && !wait_ongoing {
                        break;
                    }
                }

                let request_start = start_instant.elapsed().as_secs_f64();
                let start_latency_correction_val: Option<f64> = if latency_correction && qps.is_some() {
                    Some(job_idx as f64 / qps.unwrap())
                } else {
                    None
                };

                let url_str = if rand_regex {
                    let pattern = &url_list[0];
                    generate_rand_url(pattern, max_repeat)
                } else if url_list.len()>1 {
                    let mut rng = rand::thread_rng();
                    let idx = rng.gen_range(0..url_list.len());
                    url_list[idx].clone()
                } else {
                    url_list[0].clone()
                };

                let result = do_single_request(
                    &url_str,
                    &method,
                    &headers_raw,
                    &connect_to_raw,
                    host_override.as_deref(),
                    basic_auth.as_deref(),
                    accept_header.as_deref(),
                    content_type.as_deref(),
                    body_string.as_deref(),
                    body_from_file.as_deref(),
                    body_lines.as_deref(),
                    &forms,
                    disable_keepalive,
                    disable_compression,
                    redirect_limit,
                    timeout_opt,
                    connect_timeout,
                    &mut kept_stream,
                    &mut kept_host,
                    &mut kept_port,
                );

                let request_end = start_instant.elapsed().as_secs_f64();
                let duration = request_end - request_start;

                match result {
                    Ok((status, bytes, dns_lookup, dns_dialup, response_delay)) => {
                        total_data.fetch_add(bytes, Ordering::SeqCst);
                        let mut res = results.lock().unwrap();
                        res.push(RequestResult{
                            start: request_start,
                            dns_lookup,
                            dns_dialup,
                            response_delay,
                            duration,
                            bytes,
                            status,
                            error: None,
                            url: url_str.clone(),
                            end: request_end,
                            start_latency_correction: start_latency_correction_val,
                        });
                    },
                    Err((err_msg, dns_lookup, dns_dialup)) => {
                        let mut res = results.lock().unwrap();
                        res.push(RequestResult{
                            start: request_start,
                            dns_lookup,
                            dns_dialup,
                            response_delay: 0.0,
                            duration: 0.0,
                            bytes: 0,
                            status: 0,
                            error: Some(err_msg),
                            url: url_str.clone(),
                            end: request_end,
                            start_latency_correction: start_latency_correction_val,
                        });
                    }
                }
            }
        });
        worker_handles.push(handle);
    }

    scheduler_handle.join().ok();
    drop(job_tx);
    for h in worker_handles {
        h.join().ok();
    }

    let total_elapsed = start_instant.elapsed().as_secs_f64();

    {
        let mut res = results.lock().unwrap();
        if let Some(dur) = duration_opt {
            if !wait_ongoing {
                for r in res.iter_mut() {
                    if r.end > dur.as_secs_f64() && r.error.is_none() {
                        r.error = Some("aborted due to deadline".to_string());
                        r.status = 0;
                        r.bytes = 0;
                        r.duration = 0.0;
                    }
                }
            }
        }
    }

    let results_vec = results.lock().unwrap();
    let success_count = results_vec.iter().filter(|r| r.error.is_none()).count();
    let total_requests = if duration_opt.is_some() {
        results_vec.len()
    } else {
        n_requests
    };
    let success_rate = if total_requests>0 { success_count as f64 / total_requests as f64 } else { f64::NAN };

    let mut durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none()).map(|r| r.duration).collect();
    durations.sort_by(|a,b| a.partial_cmp(b).unwrap_or(std::cmp::Ordering::Equal));
    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let average = if !durations.is_empty() { durations.iter().sum::<f64>() / durations.len() as f64 } else { f64::NAN };

    let total_data_val = total_data.load(Ordering::SeqCst);
    let requests_per_sec = if total_elapsed>0.0 { total_requests as f64 / total_elapsed } else { 0.0 };

    let mut status_dist: BTreeMap<u16, usize> = BTreeMap::new();
    for r in results_vec.iter() {
        if r.error.is_none() && r.status!=0 {
            *status_dist.entry(r.status).or_insert(0) += 1;
        }
    }
    let mut error_dist: BTreeMap<String, usize> = BTreeMap::new();
    for r in results_vec.iter() {
        if let Some(e) = &r.error {
            *error_dist.entry(e.clone()).or_insert(0) += 1;
        }
    }

    let output_format = output_format.clone();
    let time_unit = time_unit.clone();
    let mut output_string = String::new();

    if output_format == "quiet" {
        output_string = String::new();
    } else if output_format == "json" {
        use serde_json::json;
        let mut hist_counts: BTreeMap<String, usize> = BTreeMap::new();
        if !durations.is_empty() {
            let min = fastest;
            let max = slowest;
            let step = if max>min { (max-min)/10.0 } else { 0.0 };
            for i in 0..=10 {
                let edge = if step==0.0 { min } else { min + step * i as f64 };
                let key = format!("{}", edge);
                hist_counts.insert(key, 0);
            }
            for d in &durations {
                if step==0.0 {
                    if let Some(first_key) = hist_counts.keys().next().cloned() {
                        *hist_counts.get_mut(&first_key).unwrap() += 1;
                    }
                } else {
                    let mut idx = ((d - min)/step).floor() as usize;
                    if idx>10 { idx=10; }
                    if let Some(k) = hist_counts.keys().nth(idx).cloned() {
                        *hist_counts.get_mut(&k).unwrap() += 1;
                    }
                }
            }
        } else {
            hist_counts.insert("NaN".to_string(), 0);
        }

        let percentiles = [0.10,0.25,0.50,0.75,0.90,0.95,0.99,0.999,0.9999];
        let mut latency_percentiles: BTreeMap<String, Option<f64>> = BTreeMap::new();
        for &p in &percentiles {
            let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if (p*100.0) as usize==10 { "10" } else if (p*100.0) as usize==25 { "25" } else if (p*100.0) as usize==50 { "50" } else if (p*100.0) as usize==75 { "75" } else if (p*100.0) as usize==90 { "90" } else if (p*100.0) as usize==95 { "95" } else if (p*100.0) as usize==99 { "99" } else { "" });
            let val = if durations.is_empty() {
                None
            } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                Some(durations[idx])
            };
            latency_percentiles.insert(key, val);
        }

        let mut end_times: Vec<f64> = results_vec.iter().map(|r| r.end).collect();
        end_times.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut rps_values: Vec<f64> = Vec::new();
        if end_times.len()>1 {
            for i in 1..end_times.len() {
                let delta = end_times[i] - end_times[i-1];
                if delta>0.0 {
                    rps_values.push(1.0/delta);
                }
            }
        }
        if rps_values.is_empty() && !end_times.is_empty() {
            rps_values.push(requests_per_sec);
        }
        rps_values.sort_by(|a,b| a.partial_cmp(b).unwrap());

        let rps_mean = if !rps_values.is_empty() { rps_values.iter().sum::<f64>()/rps_values.len() as f64 } else { f64::NAN };
        let rps_max = rps_values.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let rps_min = rps_values.iter().cloned().fold(f64::INFINITY, f64::min);
        let rps_stddev = if rps_values.len()>1 {
            let mean = rps_mean;
            let var = rps_values.iter().map(|v| (v-mean)*(v-mean)).sum::<f64>()/rps_values.len() as f64;
            Some(var.sqrt())
        } else {
            None
        };
        let mut rps_percentiles: BTreeMap<String, Option<f64>> = BTreeMap::new();
        for &p in &percentiles {
            let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if (p*100.0) as usize==10 { "10" } else if (p*100.0) as usize==25 { "25" } else if (p*100.0) as usize==50 { "50" } else if (p*100.0) as usize==75 { "75" } else if (p*100.0) as usize==90 { "90" } else if (p*100.0) as usize==95 { "95" } else if (p*100.0) as usize==99 { "99" } else { "" });
            let val = if rps_values.is_empty() {
                None
            } else {
                let idx = ((p * rps_values.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, rps_values.len()-1);
                Some(rps_values[idx])
            };
            rps_percentiles.insert(key, val);
        }

        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::NAN);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NAN);

        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::NAN);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NAN);

        let summary = json!({
            "successRate": if success_rate.is_nan() { serde_json::Value::Null } else { json!(success_rate) },
            "total": total_elapsed,
            "slowest": if slowest.is_infinite() { serde_json::Value::Null } else { json!(slowest) },
            "fastest": if fastest.is_infinite() { serde_json::Value::Null } else { json!(fastest) },
            "average": if average.is_nan() { serde_json::Value::Null } else { json!(average) },
            "requestsPerSec": requests_per_sec,
            "totalData": total_data_val,
            "sizePerRequest": if success_count>0 { json!(total_data_val / success_count) } else { serde_json::Value::Null },
            "sizePerSec": if total_elapsed>0.0 { json!(total_data_val as f64 / total_elapsed) } else { json!(0.0) },
        });

        let mut json_obj = serde_json::Map::new();
        json_obj.insert("summary".to_string(), summary);
        let hist_json: serde_json::Map<String, serde_json::Value> = hist_counts.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
        json_obj.insert("responseTimeHistogram".to_string(), serde_json::Value::Object(hist_json));
        let lp_json: serde_json::Map<String, serde_json::Value> = latency_percentiles.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect();
        json_obj.insert("latencyPercentiles".to_string(), serde_json::Value::Object(lp_json));

        if stats_breakdown {
            let mut success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            let mut not_success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=400).map(|r| r.duration).collect();
            not_success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());

            let mut success_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !success_durations.is_empty() {
                let min = success_durations.first().cloned().unwrap();
                let max = success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    success_hist.insert(format!("{}", edge), 0);
                }
                for d in &success_durations {
                    if step==0.0 {
                        if let Some(k) = success_hist.keys().next().cloned() {
                            *success_hist.get_mut(&k).unwrap()+=1;
                        }
                    } else {
                        let idx = ((d - min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k) = success_hist.keys().nth(idx).cloned() {
                            *success_hist.get_mut(&k).unwrap()+=1;
                        }
                    }
                }
            } else {
                success_hist.insert("NaN".to_string(), 0);
            }

            let mut not_success_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !not_success_durations.is_empty() {
                let min = not_success_durations.first().cloned().unwrap();
                let max = not_success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    not_success_hist.insert(format!("{}", edge), 0);
                }
                for d in &not_success_durations {
                    if step==0.0 {
                        if let Some(k) = not_success_hist.keys().next().cloned() {
                            *not_success_hist.get_mut(&k).unwrap()+=1;
                        }
                    } else {
                        let idx = ((d - min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k) = not_success_hist.keys().nth(idx).cloned() {
                            *not_success_hist.get_mut(&k).unwrap()+=1;
                        }
                    }
                }
            } else {
                not_success_hist.insert("NaN".to_string(), 0);
            }

            let mut success_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            for &p in &percentiles {
                let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if (p*100.0) as usize==10 { "10" } else if (p*100.0) as usize==25 { "25" } else if (p*100.0) as usize==50 { "50" } else if (p*100.0) as usize==75 { "75" } else if (p*100.0) as usize==90 { "90" } else if (p*100.0) as usize==95 { "95" } else if (p*100.0) as usize==99 { "99" } else { "" });
                let val = if success_durations.is_empty() {
                    None
                } else {
                    let idx = ((p * success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, success_durations.len()-1);
                    Some(success_durations[idx])
                };
                success_lp.insert(key, val);
            }

            let mut not_success_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            for &p in &percentiles {
                let key = format!("p{}", if p==0.999 { "99.9" } else if p==0.9999 { "99.99" } else if (p*100.0) as usize==10 { "10" } else if (p*100.0) as usize==25 { "25" } else if (p*100.0) as usize==50 { "50" } else if (p*100.0) as usize==75 { "75" } else if (p*100.0) as usize==90 { "90" } else if (p*100.0) as usize==95 { "95" } else if (p*100.0) as usize==99 { "99" } else { "" });
                let val = if not_success_durations.is_empty() {
                    None
                } else {
                    let idx = ((p * not_success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, not_success_durations.len()-1);
                    Some(not_success_durations[idx])
                };
                not_success_lp.insert(key, val);
            }

            let success_hist_json: serde_json::Map<String, serde_json::Value> = success_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
            json_obj.insert("responseTimeHistogramSuccessful".to_string(), serde_json::Value::Object(success_hist_json));
            let success_lp_json: serde_json::Map<String, serde_json::Value> = success_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect();
            json_obj.insert("latencyPercentilesSuccessful".to_string(), serde_json::Value::Object(success_lp_json));

            let not_success_hist_json: serde_json::Map<String, serde_json::Value> = not_success_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
            json_obj.insert("responseTimeHistogramNotSuccessful".to_string(), serde_json::Value::Object(not_success_hist_json));
            let not_success_lp_json: serde_json::Map<String, serde_json::Value> = not_success_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect();
            json_obj.insert("latencyPercentilesNotSuccessful".to_string(), serde_json::Value::Object(not_success_lp_json));
        }

        let rps_obj = json!({
            "mean": if rps_mean.is_nan() || rps_mean.is_infinite() { serde_json::Value::Null } else { json!(rps_mean) },
            "stddev": match rps_stddev { Some(v) => json!(v), None => serde_json::Value::Null },
            "max": if rps_max.is_infinite() { serde_json::Value::Null } else { json!(rps_max) },
            "min": if rps_min.is_infinite() { serde_json::Value::Null } else { json!(rps_min) },
            "percentiles": serde_json::Value::Object(rps_percentiles.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect())
        });
        json_obj.insert("rps".to_string(), rps_obj);

        let details_obj = json!({
            "DNSDialup": {
                "average": if dialup_avg.is_nan() { serde_json::Value::Null } else { json!(dialup_avg) },
                "fastest": if dialup_fast.is_nan() || dialup_fast.is_infinite() { serde_json::Value::Null } else { json!(dialup_fast) },
                "slowest": if dialup_slow.is_nan() || dialup_slow.is_infinite() { serde_json::Value::Null } else { json!(dialup_slow) },
            },
            "DNSLookup": {
                "average": if dns_avg.is_nan() { serde_json::Value::Null } else { json!(dns_avg) },
                "fastest": if dns_fast.is_nan() || dns_fast.is_infinite() { serde_json::Value::Null } else { json!(dns_fast) },
                "slowest": if dns_slow.is_nan() || dns_slow.is_infinite() { serde_json::Value::Null } else { json!(dns_slow) },
            }
        });
        json_obj.insert("details".to_string(), details_obj);

        let status_json: serde_json::Map<String, serde_json::Value> = status_dist.iter().map(|(k,v)| (k.to_string(), json!(*v))).collect();
        json_obj.insert("statusCodeDistribution".to_string(), serde_json::Value::Object(status_json));
        let error_json: serde_json::Map<String, serde_json::Value> = error_dist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect();
        json_obj.insert("errorDistribution".to_string(), serde_json::Value::Object(error_json));

        output_string = serde_json::to_string_pretty(&serde_json::Value::Object(json_obj)).unwrap();

    } else if output_format == "csv" {
        let mut s = String::new();
        s.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
        for r in results_vec.iter() {
            if r.error.is_some() { continue; }
            s.push_str(&format!("{:.9},{:.9},{:.9},{:.9},{:.9},{},{}\n",
                r.start,
                r.dns_lookup.unwrap_or(0.0),
                r.dns_dialup.unwrap_or(0.0),
                r.response_delay,
                r.duration,
                r.bytes,
                r.status
            ));
        }
        output_string = s;
    } else {
        let mut s = String::new();
        s.push_str("Summary:\n");
        let success_percent = if success_rate.is_nan() { f64::NAN } else { success_rate * 100.0 };
        s.push_str(&format!("  Success rate:\t{:.2}%\n", success_percent));
        if let Some(tu) = time_unit {
            s.push_str(&format!("  Total:\t{:.4} {}\n", convert_time(total_elapsed, &tu), tu));
            s.push_str(&format!("  Slowest:\t{:.4} {}\n", if slowest.is_infinite() { if slowest.is_sign_negative() { f64::NEG_INFINITY } else { f64::INFINITY } } else { convert_time(slowest, &tu) }, tu));
            s.push_str(&format!("  Fastest:\t{:.4} {}\n", if fastest.is_infinite() { if fastest.is_sign_negative() { f64::NEG_INFINITY } else { f64::INFINITY } } else { convert_time(fastest, &tu) }, tu));
            s.push_str(&format!("  Average:\t{:.4} {}\n", if average.is_nan() { f64::NAN } else { convert_time(average, &tu) }, tu));
        } else {
            let auto_unit = if total_elapsed < 0.000001 { "ns" } else if total_elapsed < 0.001 { "us" } else if total_elapsed < 1.0 { "ms" } else { "sec" };
            s.push_str(&format!("  Total:\t{}\n", format_time(total_elapsed, &auto_unit)));
            s.push_str(&format!("  Slowest:\t{}\n", if slowest.is_infinite() { if slowest.is_sign_negative() { "-inf ns".to_string() } else { "inf ns".to_string() } } else { format_time(slowest, &auto_unit) }));
            s.push_str(&format!("  Fastest:\t{}\n", if fastest.is_infinite() { if fastest.is_sign_negative() { "-inf ns".to_string() } else { "inf ns".to_string() } } else { format_time(fastest, &auto_unit) }));
            s.push_str(&format!("  Average:\t{}\n", if average.is_nan() { "NaN ns".to_string() } else { format_time(average, &auto_unit) }));
        }
        s.push_str(&format!("  Requests/sec:\t{:.4}\n", requests_per_sec));
        s.push_str("\n");
        s.push_str(&format!("  Total data:\t{} B\n", total_data_val));
        if success_count>0 {
            s.push_str(&format!("  Size/request:\t{} B\n", total_data_val / success_count));
        } else {
            s.push_str("  Size/request:\tNaN\n");
        }
        let size_per_sec = if total_elapsed>0.0 { total_data_val as f64 / total_elapsed } else { 0.0 };
        s.push_str(&format!("  Size/sec:\t{}\n", format_data_rate(size_per_sec)));
        s.push_str("\n");
        s.push_str("Response time histogram:\n");
        if durations.is_empty() {
            for _ in 0..11 {
                s.push_str("    NaN ns [0] |\n");
            }
        } else {
            let min = fastest;
            let max = slowest;
            let step = if max>min { (max-min)/10.0 } else { 0.0 };
            let mut bins = vec![0usize; 11];
            for d in &durations {
                if step==0.0 {
                    bins[0] +=1;
                } else {
                    let idx = ((d - min)/step).floor() as usize;
                    let idx = std::cmp::min(idx, 10);
                    bins[idx]+=1;
                }
            }
            let max_count = bins.iter().cloned().max().unwrap_or(1);
            for i in 0..=10 {
                let edge = if step==0.0 { min } else { min + step*i as f64 };
                let count = bins[i];
                let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                let time_str = if let Some(tu) = &time_unit {
                    format!("{:.4} {}", convert_time(edge, tu), tu)
                } else {
                    format_time_auto(edge)
                };
                s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
            }
        }
        s.push_str("\n");
        s.push_str("Response time distribution:\n");
        let percentiles_vals = [0.10,0.25,0.50,0.75,0.90,0.95,0.99,0.999,0.9999];
        let percentile_labels = ["10.00%","25.00%","50.00%","75.00%","90.00%","95.00%","99.00%","99.90%","99.99%"];
        for (i,&p) in percentiles_vals.iter().enumerate() {
            let val = if durations.is_empty() {
                "NaN ns".to_string()
            } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                let d = durations[idx];
                if let Some(tu) = &time_unit {
                    format!("{:.4} {}", convert_time(d, tu), tu)
                } else {
                    format_time_auto(d)
                }
            };
            s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
        }
        s.push_str("\n");
        s.push_str("\n");
        if stats_breakdown {
            let mut success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (2xx only):\n");
            if success_durations.is_empty() {
                for _ in 0..11 {
                    s.push_str("    NaN ns [0] |\n");
                }
            } else {
                let min = success_durations.first().cloned().unwrap();
                let max = success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &success_durations {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let max_count = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let count = bins[i];
                    let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let time_str = if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(edge, tu), tu)
                    } else {
                        format_time_auto(edge)
                    };
                    s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (2xx only):\n");
            for (i,&p) in percentiles_vals.iter().enumerate() {
                let val = if success_durations.is_empty() {
                    "NaN ns".to_string()
                } else {
                    let idx = ((p * success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, success_durations.len()-1);
                    let d = success_durations[idx];
                    if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(d, tu), tu)
                    } else {
                        format_time_auto(d)
                    }
                };
                s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
            }
            s.push_str("\n");
            s.push_str("\n");
            let mut not_success_durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=400).map(|r| r.duration).collect();
            not_success_durations.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (4xx + 5xx only):\n");
            if not_success_durations.is_empty() {
                for _ in 0..11 {
                    s.push_str("    NaN ns [0] |\n");
                }
            } else {
                let min = not_success_durations.first().cloned().unwrap();
                let max = not_success_durations.last().cloned().unwrap();
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &not_success_durations {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let max_count = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min + step*i as f64 };
                    let count = bins[i];
                    let bar_len = if max_count>0 { (count as f64 / max_count as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if count>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let time_str = if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(edge, tu), tu)
                    } else {
                        format_time_auto(edge)
                    };
                    s.push_str(&format!("  {} [{}] |{}\n", time_str, count, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (4xx + 5xx only):\n");
            for (i,&p) in percentiles_vals.iter().enumerate() {
                let val = if not_success_durations.is_empty() {
                    "NaN ns".to_string()
                } else {
                    let idx = ((p * not_success_durations.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, not_success_durations.len()-1);
                    let d = not_success_durations[idx];
                    if let Some(tu) = &time_unit {
                        format!("{:.4} {}", convert_time(d, tu), tu)
                    } else {
                        format_time_auto(d)
                    }
                };
                s.push_str(&format!("  {} in {}\n", percentile_labels[i], val));
            }
            s.push_str("\n");
            s.push_str("\n");
        }

        s.push_str("\n");
        s.push_str("Details (average, fastest, slowest):\n");
        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);
        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);

        if let Some(tu) = &time_unit {
            s.push_str(&format!("  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dialup_avg.is_nan() { f64::NAN } else { convert_time(dialup_avg, tu) },
                tu,
                if dialup_fast.is_infinite() { f64::INFINITY } else { convert_time(dialup_fast, tu) },
                tu,
                if dialup_slow.is_infinite() && dialup_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dialup_slow, tu) },
                tu
            ));
            s.push_str(&format!("  DNS-lookup:\t{:.4} {}, {:.4} {}, {:.4} {}\n",
                if dns_avg.is_nan() { f64::NAN } else { convert_time(dns_avg, tu) },
                tu,
                if dns_fast.is_infinite() { f64::INFINITY } else { convert_time(dns_fast, tu) },
                tu,
                if dns_slow.is_infinite() && dns_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dns_slow, tu) },
                tu
            ));
        } else {
            s.push_str(&format!("  DNS+dialup:\t{}, {}, {}\n",
                format_time_auto(dialup_avg),
                format_time_auto(dialup_fast),
                format_time_auto(dialup_slow)
            ));
            s.push_str(&format!("  DNS-lookup:\t{}, {}, {}\n",
                format_time_auto(dns_avg),
                format_time_auto(dns_fast),
                format_time_auto(dns_slow)
            ));
        }
        s.push_str("\n");
        s.push_str("Status code distribution:\n");
        for (code, count) in status_dist.iter() {
            s.push_str(&format!("  [{}] {} responses\n", code, count));
        }
        if !error_dist.is_empty() {
            s.push_str("\n");
            s.push_str("Error distribution:\n");
            for (msg, count) in error_dist.iter() {
                s.push_str(&format!("  [{}] {}\n", count, msg));
            }
        }

        output_string = s;
    }

    if let Some(db_path) = db_url {
        let mut insert_values_correct: Vec<String> = Vec::new();
        for r in results_vec.iter() {
            if r.error.is_none() {
                let url_for_db = match url::Url::parse(&r.url) {
                    Ok(u) => u.path().to_string(),
                    Err(_) => r.url.clone(),
                };
                let url_escaped = url_for_db.replace('\'', "''");
                let start = r.start;
                let end = r.end;
                let duration = r.duration;
                let status = r.status;
                let len = r.bytes;
                let run = run_unix_timestamp;
                match r.start_latency_correction {
                    Some(lc) => {
                        insert_values_correct.push(format!("('{}',{},{},{},{},{},{},{})", url_escaped, start, lc, end, duration, status, len, run));
                    },
                    None => {
                        insert_values_correct.push(format!("('{}',{},NULL,{},{},{},{},{})", url_escaped, start, end, duration, status, len, run));
                    }
                }
            }
        }

        let mut python_code = String::new();
        python_code.push_str("import sqlite3, sys\n");
        python_code.push_str(&format!("con=sqlite3.connect(r\"{}\")\n", db_path.replace('"', "\\\"")));
        python_code.push_str("cur=con.cursor()\n");
        python_code.push_str("cur.execute('''CREATE TABLE IF NOT EXISTS oha (\n            url TEXT NOT NULL,\n            start REAL NOT NULL,\n            start_latency_correction REAL,\n            end REAL NOT NULL,\n            duration REAL NOT NULL,\n            status INTEGER NOT NULL,\n            len_bytes INTEGER NOT NULL,\n            run INTEGER NOT NULL\n        )''')\n");
        for val in insert_values_correct {
            python_code.push_str(&format!("cur.execute('INSERT INTO oha VALUES {}')\n", val));
        }
        python_code.push_str("con.commit()\n");
        python_code.push_str("con.close()\n");

        let mut child = std::process::Command::new("python3")
            .arg("-c")
            .arg(python_code)
            .spawn();
        if let Ok(mut child) = child {
            let _ = child.wait();
        }

        output_string.push_str(&format!("\nStoring results to {}\n", db_path));
    }

    if let Some(out_path) = output_path {
        if let Err(e) = std::fs::write(&out_path, output_string.as_bytes()) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else {
        print!("{}", output_string);
    }
}

