        url_list.push(url_arg.clone());
    }

    let body_from_file: Option<Vec<u8>> = if let Some(p) = body_path {
        match std::fs::read(&p) {
            Ok(b) => Some(b),
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else { None };

    let body_lines: Option<Vec<Vec<u8>>> = if let Some(p) = body_lines_path {
        match std::fs::read_to_string(&p) {
            Ok(content) => {
                let lines: Vec<Vec<u8>> = content.lines().map(|l| l.as_bytes().to_vec()).collect();
                Some(if lines.is_empty() { vec![b"".to_vec()] } else { lines })
            },
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else { None };

    struct R {
        start: f64,
        dns_lookup: Option<f64>,
        dns_dialup: Option<f64>,
        response_delay: f64,
        duration: f64,
        bytes: usize,
        status: u16,
        error: Option<String>,
        url: String,
        end: f64,
    }

    let results = Arc::new(Mutex::new(Vec::<R>::new()));
    let total_data = Arc::new(AtomicUsize::new(0));
    let start_instant = Instant::now();
    let run_ts = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_secs();

    let (job_tx, job_rx_raw) = std::sync::mpsc::channel::<Option<usize>>();
    let job_rx = Arc::new(Mutex::new(job_rx_raw));

    let scheduler = {
        let job_tx = job_tx.clone();
        let duration_opt = duration_opt.clone();
        let qps = qps.clone();
        let burst_delay_opt = burst_delay_opt.clone();
        let burst_rate = burst_rate;
        let n_requests = n_requests;
        thread::spawn(move || {
            if let Some(dur) = duration_opt {
                let start = Instant::now();
                let mut count = 0usize;
                if let Some(q) = qps {
                    let interval = Duration::from_secs_f64(1.0 / q);
                    while start.elapsed() < dur {
                        let _ = job_tx.send(Some(count));
                        count+=1;
                        thread::sleep(interval);
                    }
                } else if let Some(bd) = burst_delay_opt {
                    while start.elapsed() < dur {
                        for _ in 0..burst_rate {
                            if start.elapsed() >= dur { break; }
                            let _ = job_tx.send(Some(count));
                            count+=1;
                        }
                        thread::sleep(bd);
                    }
                } else {
                    while start.elapsed() < dur {
                        let _ = job_tx.send(Some(count));
                        count+=1;
                        thread::sleep(Duration::from_millis(1));
                    }
                }
            } else {
                if let Some(q) = qps {
                    let interval = Duration::from_secs_f64(1.0 / q);
                    for i in 0..n_requests {
                        let _ = job_tx.send(Some(i));
                        if i+1 < n_requests { thread::sleep(interval); }
                    }
                } else if let Some(bd) = burst_delay_opt {
                    let mut sent=0;
                    while sent < n_requests {
                        for _ in 0..burst_rate {
                            if sent>=n_requests { break; }
                            let _ = job_tx.send(Some(sent));
                            sent+=1;
                        }
                        if sent < n_requests { thread::sleep(bd); }
                    }
                } else {
                    for i in 0..n_requests { let _ = job_tx.send(Some(i)); }
                }
            }
        })
    };

    let mut workers = Vec::new();
    let total_conc = if n_connections==0 {1} else { n_connections };
    for _ in 0..total_conc {
        let job_rx = job_rx.clone();
        let results = results.clone();
        let total_data = total_data.clone();
        let url_list = url_list.clone();
        let method = method.clone();
        let headers_raw = headers_raw.clone();
        let connect_to_raw = connect_to_raw.clone();
        let host_override = host_override.clone();
        let basic_auth = basic_auth.clone();
        let accept_header = accept_header.clone();
        let content_type = content_type.clone();
        let body_string = body_string.clone();
        let body_from_file = body_from_file.clone();
        let body_lines = body_lines.clone();
        let forms = forms.clone();
        let disable_keepalive = disable_keepalive;
        let disable_compression = disable_compression;
        let redirect_limit = redirect_limit;
        let timeout_opt = timeout_opt.clone();
        let connect_timeout = connect_timeout.clone();
        let rand_regex = rand_regex;
        let max_repeat = max_repeat;
        let start_instant = start_instant.clone();
        let duration_opt = duration_opt.clone();
        let wait_ongoing = wait_ongoing;
        let handle = thread::spawn(move || {
            let mut kept_stream: Option<std::net::TcpStream> = None;
            let mut kept_host = String::new();
            let mut kept_port: u16 = 0;
            loop {
                let job = {
                    let rx = job_rx.lock().unwrap();
                    rx.recv().ok()
                };
                let _job_idx = match job {
                    Some(Some(idx)) => idx,
                    Some(None) => break,
                    None => break,
                };
                if let Some(dur) = duration_opt {
                    if start_instant.elapsed() >= dur && !wait_ongoing { break; }
                }
                let rs = start_instant.elapsed().as_secs_f64();
                let url_str = if rand_regex {
                    generate_rand_url(&url_list[0], max_repeat)
                } else if url_list.len()>1 {
                    let mut rng = rand::thread_rng();
                    let idx = rng.gen_range(0..url_list.len());
                    url_list[idx].clone()
                } else {
                    url_list[0].clone()
                };
                let res = do_single_request(&url_str, &method, &headers_raw, &connect_to_raw, host_override.as_deref(), basic_auth.as_deref(), accept_header.as_deref(), content_type.as_deref(), body_string.as_deref(), body_from_file.as_deref(), body_lines.as_deref(), &forms, disable_keepalive, disable_compression, redirect_limit, timeout_opt, connect_timeout, &mut kept_stream, &mut kept_host, &mut kept_port);
                let re = start_instant.elapsed().as_secs_f64();
                let dur = re - rs;
                match res {
                    Ok((status, bytes, dns_l, dns_d, resp_delay)) => {
                        total_data.fetch_add(bytes, Ordering::SeqCst);
                        let mut rr = results.lock().unwrap();
                        rr.push(R{ start: rs, dns_lookup: dns_l, dns_dialup: dns_d, response_delay: resp_delay, duration: dur, bytes, status, error: None, url: url_str, end: re });
                    },
                    Err((msg, dns_l, dns_d)) => {
                        let mut rr = results.lock().unwrap();
                        rr.push(R{ start: rs, dns_lookup: dns_l, dns_dialup: dns_d, response_delay: 0.0, duration: 0.0, bytes:0, status:0, error:Some(msg), url: url_str, end: re });
                    }
                }
            }
        });
        workers.push(handle);
    }

    scheduler.join().ok();
    drop(job_tx);
    for h in workers { h.join().ok(); }

    let total_elapsed = start_instant.elapsed().as_secs_f64();
    {
        let mut res = results.lock().unwrap();
        if let Some(dur) = duration_opt {
            if !wait_ongoing {
                for r in res.iter_mut() {
                    if r.end > dur.as_secs_f64() && r.error.is_none() {
                        r.error = Some("aborted due to deadline".to_string());
                        r.status=0;
                        r.bytes=0;
                        r.duration=0.0;
                    }
                }
            }
        }
    }

    let results_vec = results.lock().unwrap();
    let success_count = results_vec.iter().filter(|r| r.error.is_none()).count();
    let total_requests = if duration_opt.is_some() { results_vec.len() } else { n_requests };
    let success_rate = if total_requests>0 { success_count as f64 / total_requests as f64 } else { f64::NAN };

    let mut durations: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none()).map(|r| r.duration).collect();
    durations.sort_by(|a,b| a.partial_cmp(b).unwrap());

    let slowest = durations.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
    let fastest = durations.iter().cloned().fold(f64::INFINITY, f64::min);
    let average = if !durations.is_empty() { durations.iter().sum::<f64>() / durations.len() as f64 } else { f64::NAN };
    let total_data_val = total_data.load(Ordering::SeqCst);
    let req_per_sec = if total_elapsed>0.0 { total_requests as f64 / total_elapsed } else { 0.0 };

    let mut status_dist: BTreeMap<u16, usize> = BTreeMap::new();
    for r in results_vec.iter() {
        if r.error.is_none() && r.status!=0 {
            *status_dist.entry(r.status).or_insert(0)+=1;
        }
    }
    let mut error_dist: BTreeMap<String, usize> = BTreeMap::new();
    for r in results_vec.iter() {
        if let Some(e)=&r.error {
            *error_dist.entry(e.clone()).or_insert(0)+=1;
        }
    }

    let mut out_str = String::new();

    if output_format=="quiet" {
        out_str = String::new();
    } else if output_format=="json" {
        use serde_json::json;
        let mut hist_counts: BTreeMap<String, usize> = BTreeMap::new();
        if !durations.is_empty() {
            let min = fastest;
            let max = slowest;
            let step = if max>min { (max-min)/10.0 } else { 0.0 };
            for i in 0..=10 {
                let edge = if step==0.0 { min } else { min + step*i as f64 };
                hist_counts.insert(format!("{}", edge), 0);
            }
            for d in &durations {
                if step==0.0 {
                    if let Some(k)=hist_counts.keys().next().cloned() {
                        *hist_counts.get_mut(&k).unwrap()+=1;
                    }
                } else {
                    let mut idx = ((d - min)/step).floor() as usize;
                    if idx>10 { idx=10; }
                    if let Some(k)=hist_counts.keys().nth(idx).cloned() {
                        *hist_counts.get_mut(&k).unwrap()+=1;
                    }
                }
            }
        } else {
            hist_counts.insert("NaN".to_string(),0);
        }

        let percentiles = [0.10,0.25,0.50,0.75,0.90,0.95,0.99,0.999,0.9999];
        let mut lat_pct: BTreeMap<String, Option<f64>> = BTreeMap::new();
        for &p in &percentiles {
            let key = format!("p{}", match p { x if x==0.999 => "99.9".to_string(), x if x==0.9999 => "99.99".to_string(), x => format!("{}", (x*100.0) as usize) });
            let val = if durations.is_empty() { None } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                Some(durations[idx])
            };
            lat_pct.insert(key,val);
        }

        let mut end_times: Vec<f64> = results_vec.iter().map(|r| r.end).collect();
        end_times.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let mut rps_vals: Vec<f64> = Vec::new();
        if end_times.len()>1 {
            for i in 1..end_times.len() {
                let d = end_times[i]-end_times[i-1];
                if d>0.0 { rps_vals.push(1.0/d); }
            }
        }
        if rps_vals.is_empty() && !end_times.is_empty() { rps_vals.push(req_per_sec); }
        rps_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let rps_mean = if !rps_vals.is_empty() { rps_vals.iter().sum::<f64>()/rps_vals.len() as f64 } else { f64::NAN };
        let rps_max = rps_vals.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let rps_min = rps_vals.iter().cloned().fold(f64::INFINITY, f64::min);
        let rps_stddev = if rps_vals.len()>1 {
            let m = rps_mean;
            let var = rps_vals.iter().map(|v| (v-m)*(v-m)).sum::<f64>()/rps_vals.len() as f64;
            Some(var.sqrt())
        } else { None };
        let mut rps_pct: BTreeMap<String, Option<f64>> = BTreeMap::new();
        for &p in &percentiles {
            let key = format!("p{}", match p { x if x==0.999 => "99.9".to_string(), x if x==0.9999 => "99.99".to_string(), x => format!("{}", (x*100.0) as usize) });
            let val = if rps_vals.is_empty() { None } else {
                let idx = ((p * rps_vals.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, rps_vals.len()-1);
                Some(rps_vals[idx])
            };
            rps_pct.insert(key,val);
        }

        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::NAN);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NAN);
        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::NAN);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NAN);

        let mut json_obj = serde_json::Map::new();
        json_obj.insert("summary".to_string(), json!({
            "successRate": if success_rate.is_nan() { serde_json::Value::Null } else { json!(success_rate) },
            "total": total_elapsed,
            "slowest": if slowest.is_infinite() { serde_json::Value::Null } else { json!(slowest) },
            "fastest": if fastest.is_infinite() { serde_json::Value::Null } else { json!(fastest) },
            "average": if average.is_nan() { serde_json::Value::Null } else { json!(average) },
            "requestsPerSec": req_per_sec,
            "totalData": total_data_val,
            "sizePerRequest": if success_count>0 { json!(total_data_val / success_count) } else { serde_json::Value::Null },
            "sizePerSec": if total_elapsed>0.0 { json!(total_data_val as f64 / total_elapsed) } else { json!(0.0) },
        }));
        json_obj.insert("responseTimeHistogram".to_string(), serde_json::Value::Object(hist_counts.iter().map(|(k,v)| (k.clone(), json!(*v))).collect()));
        json_obj.insert("latencyPercentiles".to_string(), serde_json::Value::Object(lat_pct.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect()));

        if stats_breakdown {
            let mut succ_durs: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            succ_durs.sort_by(|a,b| a.partial_cmp(b).unwrap());
            let mut fail_durs: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=400).map(|r| r.duration).collect();
            fail_durs.sort_by(|a,b| a.partial_cmp(b).unwrap());

            let mut succ_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !succ_durs.is_empty() {
                let min = succ_durs[0];
                let max = succ_durs[succ_durs.len()-1];
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 { succ_hist.insert(format!("{}", if step==0.0 { min } else { min+step*i as f64 }),0); }
                for d in &succ_durs {
                    if step==0.0 {
                        if let Some(k)=succ_hist.keys().next().cloned() { *succ_hist.get_mut(&k).unwrap()+=1; }
                    } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k)=succ_hist.keys().nth(idx).cloned() { *succ_hist.get_mut(&k).unwrap()+=1; }
                    }
                }
            } else { succ_hist.insert("NaN".to_string(),0); }

            let mut fail_hist: BTreeMap<String, usize> = BTreeMap::new();
            if !fail_durs.is_empty() {
                let min = fail_durs[0];
                let max = fail_durs[fail_durs.len()-1];
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 { fail_hist.insert(format!("{}", if step==0.0 { min } else { min+step*i as f64 }),0); }
                for d in &fail_durs {
                    if step==0.0 {
                        if let Some(k)=fail_hist.keys().next().cloned() { *fail_hist.get_mut(&k).unwrap()+=1; }
                    } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k)=fail_hist.keys().nth(idx).cloned() { *fail_hist.get_mut(&k).unwrap()+=1; }
                    }
                }
            } else { fail_hist.insert("NaN".to_string(),0); }

            let mut succ_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            let mut fail_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            for &p in &percentiles {
                let key = format!("p{}", match p { x if x==0.999 => "99.9".to_string(), x if x==0.9999 => "99.99".to_string(), x => format!("{}", (x*100.0) as usize) });
                let sv = if succ_durs.is_empty() { None } else {
                    let idx = ((p * succ_durs.len() as f64).ceil() as usize).saturating_sub(1);
                    Some(succ_durs[std::cmp::min(idx, succ_durs.len()-1)])
                };
                let fv = if fail_durs.is_empty() { None } else {
                    let idx = ((p * fail_durs.len() as f64).ceil() as usize).saturating_sub(1);
                    Some(fail_durs[std::cmp::min(idx, fail_durs.len()-1)])
                };
                succ_lp.insert(key.clone(), sv);
                fail_lp.insert(key, fv);
            }

            json_obj.insert("responseTimeHistogramSuccessful".to_string(), serde_json::Value::Object(succ_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect()));
            json_obj.insert("latencyPercentilesSuccessful".to_string(), serde_json::Value::Object(succ_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect()));
            json_obj.insert("responseTimeHistogramNotSuccessful".to_string(), serde_json::Value::Object(fail_hist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect()));
            json_obj.insert("latencyPercentilesNotSuccessful".to_string(), serde_json::Value::Object(fail_lp.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect()));
        }

        json_obj.insert("rps".to_string(), json!({
            "mean": if rps_mean.is_nan() || rps_mean.is_infinite() { serde_json::Value::Null } else { json!(rps_mean) },
            "stddev": match rps_stddev { Some(v) => json!(v), None => serde_json::Value::Null },
            "max": if rps_max.is_infinite() { serde_json::Value::Null } else { json!(rps_max) },
            "min": if rps_min.is_infinite() { serde_json::Value::Null } else { json!(rps_min) },
            "percentiles": serde_json::Value::Object(rps_pct.iter().map(|(k,v)| (k.clone(), match v { Some(val) => json!(*val), None => serde_json::Value::Null })).collect())
        }));
        json_obj.insert("details".to_string(), json!({
            "DNSDialup": {
                "average": if dialup_avg.is_nan() { serde_json::Value::Null } else { json!(dialup_avg) },
                "fastest": if dialup_fast.is_nan() || dialup_fast.is_infinite() { serde_json::Value::Null } else { json!(dialup_fast) },
                "slowest": if dialup_slow.is_nan() || dialup_slow.is_infinite() { serde_json::Value::Null } else { json!(dialup_slow) },
            },
            "DNSLookup": {
                "average": if dns_avg.is_nan() { serde_json::Value::Null } else { json!(dns_avg) },
                "fastest": if dns_fast.is_nan() || dns_fast.is_infinite() { serde_json::Value::Null } else { json!(dns_fast) },
                "slowest": if dns_slow.is_nan() || dns_slow.is_infinite() { serde_json::Value::Null } else { json!(dns_slow) },
            }
        }));
        json_obj.insert("statusCodeDistribution".to_string(), serde_json::Value::Object(status_dist.iter().map(|(k,v)| (k.to_string(), json!(*v))).collect()));
        json_obj.insert("errorDistribution".to_string(), serde_json::Value::Object(error_dist.iter().map(|(k,v)| (k.clone(), json!(*v))).collect()));

        out_str = serde_json::to_string_pretty(&serde_json::Value::Object(json_obj)).unwrap();
    } else if output_format=="csv" {
        let mut s = String::new();
        s.push_str("request-start,DNS,DNS+dialup,Response-delay,request-duration,bytes,status\n");
        for r in results_vec.iter() {
            if r.error.is_some() { continue; }
            s.push_str(&format!("{:.9},{:.9},{:.9},{:.9},{:.9},{},{}\n", r.start, r.dns_lookup.unwrap_or(0.0), r.dns_dialup.unwrap_or(0.0), r.response_delay, r.duration, r.bytes, r.status));
        }
        out_str = s;
    } else {
        let mut s = String::new();
        s.push_str("Summary:\n");
        let success_percent = if success_rate.is_nan() { f64::NAN } else { success_rate*100.0 };
        s.push_str(&format!("  Success rate:\t{:.2}%\n", success_percent));
        if let Some(tu) = time_unit {
            s.push_str(&format!("  Total:\t{:.4} {}\n", convert_time(total_elapsed, &tu), tu));
            s.push_str(&format!("  Slowest:\t{:.4} {}\n", if slowest.is_infinite() { if slowest.is_sign_negative() { f64::NEG_INFINITY } else { f64::INFINITY } } else { convert_time(slowest, &tu) }, tu));
            s.push_str(&format!("  Fastest:\t{:.4} {}\n", if fastest.is_infinite() { if fastest.is_sign_negative() { f64::NEG_INFINITY } else { f64::INFINITY } } else { convert_time(fastest, &tu) }, tu));
            s.push_str(&format!("  Average:\t{:.4} {}\n", if average.is_nan() { f64::NAN } else { convert_time(average, &tu) }, tu));
        } else {
            let auto_unit = if total_elapsed < 0.000001 { "ns" } else if total_elapsed < 0.001 { "us" } else if total_elapsed < 1.0 { "ms" } else { "sec" };
            s.push_str(&format!("  Total:\t{}\n", format_time(total_elapsed, &auto_unit)));
            s.push_str(&format!("  Slowest:\t{}\n", if slowest.is_infinite() { if slowest.is_sign_negative() { "-inf ns".to_string() } else { "inf ns".to_string() } } else { format_time(slowest, &auto_unit) }));
            s.push_str(&format!("  Fastest:\t{}\n", if fastest.is_infinite() { if fastest.is_sign_negative() { "-inf ns".to_string() } else { "inf ns".to_string() } } else { format_time(fastest, &auto_unit) }));
            s.push_str(&format!("  Average:\t{}\n", if average.is_nan() { "NaN ns".to_string() } else { format_time(average, &auto_unit) }));
        }
        s.push_str(&format!("  Requests/sec:\t{:.4}\n", req_per_sec));
        s.push_str("\n");
        s.push_str(&format!("  Total data:\t{} B\n", total_data_val));
        if success_count>0 {
            s.push_str(&format!("  Size/request:\t{} B\n", total_data_val / success_count));
        } else {
            s.push_str("  Size/request:\tNaN\n");
        }
        let size_per_sec = if total_elapsed>0.0 { total_data_val as f64 / total_elapsed } else { 0.0 };
        s.push_str(&format!("  Size/sec:\t{}\n", format_data_rate(size_per_sec)));
        s.push_str("\n");
        s.push_str("Response time histogram:\n");
        if durations.is_empty() {
            for _ in 0..11 { s.push_str("    NaN ns [0] |\n"); }
        } else {
            let min = fastest;
            let max = slowest;
            let step = if max>min { (max-min)/10.0 } else { 0.0 };
            let mut bins = vec![0usize;11];
            for d in &durations {
                if step==0.0 { bins[0]+=1; } else {
                    let idx = ((d-min)/step).floor() as usize;
                    let idx = std::cmp::min(idx,10);
                    bins[idx]+=1;
                }
            }
            let maxc = bins.iter().cloned().max().unwrap_or(1);
            for i in 0..=10 {
                let edge = if step==0.0 { min } else { min+step*i as f64 };
                let cnt = bins[i];
                let bar_len = if maxc>0 { (cnt as f64 / maxc as f64 * 32.0).round() as usize } else { 0 };
                let bar = if cnt>0 { "■".repeat(bar_len) } else { "".to_string() };
                let tstr = if let Some(tu)=&time_unit {
                    format!("{:.4} {}", convert_time(edge, tu), tu)
                } else {
                    format_time_auto(edge)
                };
                s.push_str(&format!("  {} [{}] |{}\n", tstr, cnt, bar));
            }
        }
        s.push_str("\n");
        s.push_str("Response time distribution:\n");
        let perc_vals = [0.10,0.25,0.50,0.75,0.90,0.95,0.99,0.999,0.9999];
        let labels = ["10.00%","25.00%","50.00%","75.00%","90.00%","95.00%","99.00%","99.90%","99.99%"];
        for (i,&p) in perc_vals.iter().enumerate() {
            let val = if durations.is_empty() { "NaN ns".to_string() } else {
                let idx = ((p * durations.len() as f64).ceil() as usize).saturating_sub(1);
                let idx = std::cmp::min(idx, durations.len()-1);
                let d = durations[idx];
                if let Some(tu)=&time_unit { format!("{:.4} {}", convert_time(d, tu), tu) } else { format_time_auto(d) }
            };
            s.push_str(&format!("  {} in {}\n", labels[i], val));
        }
        s.push_str("\n\n");
        if stats_breakdown {
            let mut succ_durs: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=200 && r.status<400).map(|r| r.duration).collect();
            succ_durs.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (2xx only):\n");
            if succ_durs.is_empty() {
                for _ in 0..11 { s.push_str("    NaN ns [0] |\n"); }
            } else {
                let min = succ_durs[0];
                let max = succ_durs[succ_durs.len()-1];
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &succ_durs {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let maxc = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min+step*i as f64 };
                    let cnt = bins[i];
                    let bar_len = if maxc>0 { (cnt as f64 / maxc as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if cnt>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let tstr = if let Some(tu)=&time_unit { format!("{:.4} {}", convert_time(edge, tu), tu) } else { format_time_auto(edge) };
                    s.push_str(&format!("  {} [{}] |{}\n", tstr, cnt, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (2xx only):\n");
            for (i,&p) in perc_vals.iter().enumerate() {
                let val = if succ_durs.is_empty() { "NaN ns".to_string() } else {
                    let idx = ((p * succ_durs.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, succ_durs.len()-1);
                    let d = succ_durs[idx];
                    if let Some(tu)=&time_unit { format!("{:.4} {}", convert_time(d, tu), tu) } else { format_time_auto(d) }
                };
                s.push_str(&format!("  {} in {}\n", labels[i], val));
            }
            s.push_str("\n\n");
            let mut fail_durs: Vec<f64> = results_vec.iter().filter(|r| r.error.is_none() && r.status>=400).map(|r| r.duration).collect();
            fail_durs.sort_by(|a,b| a.partial_cmp(b).unwrap());
            s.push_str("Response time histogram (4xx + 5xx only):\n");
            if fail_durs.is_empty() {
                for _ in 0..11 { s.push_str("    NaN ns [0] |\n"); }
            } else {
                let min = fail_durs[0];
                let max = fail_durs[fail_durs.len()-1];
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                let mut bins = vec![0usize;11];
                for d in &fail_durs {
                    if step==0.0 { bins[0]+=1; } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        bins[idx]+=1;
                    }
                }
                let maxc = bins.iter().cloned().max().unwrap_or(1);
                for i in 0..=10 {
                    let edge = if step==0.0 { min } else { min+step*i as f64 };
                    let cnt = bins[i];
                    let bar_len = if maxc>0 { (cnt as f64 / maxc as f64 * 32.0).round() as usize } else { 0 };
                    let bar = if cnt>0 { "■".repeat(bar_len) } else { "".to_string() };
                    let tstr = if let Some(tu)=&time_unit { format!("{:.4} {}", convert_time(edge, tu), tu) } else { format_time_auto(edge) };
                    s.push_str(&format!("  {} [{}] |{}\n", tstr, cnt, bar));
                }
            }
            s.push_str("\n");
            s.push_str("Response time distribution (4xx + 5xx only):\n");
            for (i,&p) in perc_vals.iter().enumerate() {
                let val = if fail_durs.is_empty() { "NaN ns".to_string() } else {
                    let idx = ((p * fail_durs.len() as f64).ceil() as usize).saturating_sub(1);
                    let idx = std::cmp::min(idx, fail_durs.len()-1);
                    let d = fail_durs[idx];
                    if let Some(tu)=&time_unit { format!("{:.4} {}", convert_time(d, tu), tu) } else { format_time_auto(d) }
                };
                s.push_str(&format!("  {} in {}\n", labels[i], val));
            }
            s.push_str("\n\n");
        }
        s.push_str("\n");
        s.push_str("Details (average, fastest, slowest):\n");
        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dialup_avg = if !dns_dialup_vals.is_empty() { dns_dialup_vals.iter().sum::<f64>()/dns_dialup_vals.len() as f64 } else { f64::NAN };
        let dialup_fast = dns_dialup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dialup_slow = dns_dialup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);
        let mut dns_lookup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_lookup).collect();
        dns_lookup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
        let dns_avg = if !dns_lookup_vals.is_empty() { dns_lookup_vals.iter().sum::<f64>()/dns_lookup_vals.len() as f64 } else { f64::NAN };
        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::INFINITY);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NEG_INFINITY);
        if let Some(tu)=&time_unit {
            s.push_str(&format!("  DNS+dialup:\t{:.4} {}, {:.4} {}, {:.4} {}\n", if dialup_avg.is_nan() { f64::NAN } else { convert_time(dialup_avg, tu) }, tu, if dialup_fast.is_infinite() { f64::INFINITY } else { convert_time(dialup_fast, tu) }, tu, if dialup_slow.is_infinite() && dialup_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dialup_slow, tu) }, tu));
            s.push_str(&format!("  DNS-lookup:\t{:.4} {}, {:.4} {}, {:.4} {}\n", if dns_avg.is_nan() { f64::NAN } else { convert_time(dns_avg, tu) }, tu, if dns_fast.is_infinite() { f64::INFINITY } else { convert_time(dns_fast, tu) }, tu, if dns_slow.is_infinite() && dns_slow.is_sign_negative() { f64::NEG_INFINITY } else { convert_time(dns_slow, tu) }, tu));
        } else {
            s.push_str(&format!("  DNS+dialup:\t{}, {}, {}\n", format_time_auto(dialup_avg), format_time_auto(dialup_fast), format_time_auto(dialup_slow)));
            s.push_str(&format!("  DNS-lookup:\t{}, {}, {}\n", format_time_auto(dns_avg), format_time_auto(dns_fast), format_time_auto(dns_slow)));
        }
        s.push_str("\n");
        s.push_str("Status code distribution:\n");
        for (code,cnt) in status_dist.iter() {
            s.push_str(&format!("  [{}] {} responses\n", code, cnt));
        }
        if !error_dist.is_empty() {
            s.push_str("\n");
            s.push_str("Error distribution:\n");
            for (msg,cnt) in error_dist.iter() {
                s.push_str(&format!("  [{}] {}\n", cnt, msg));
            }
        }
        out_str = s;
    }

    if let Some(db_path) = db_url {
        let mut insert_vals: Vec<String> = Vec::new();
        for r in results_vec.iter() {
            if r.error.is_none() {
                let url_for_db = match url::Url::parse(&r.url) {
                    Ok(u) => u.path().to_string(),
                    Err(_) => r.url.clone(),
                };
                let esc = url_for_db.replace('\'',"''");
                insert_vals.push(format!("('{}',{:.9},NULL,{:.9},{:.9},{},{},{})", esc, r.start, r.end, r.duration, r.status, r.bytes, run_ts));
            }
        }
        let mut py = String::new();
        py.push_str("import sqlite3\n");
        py.push_str(&format!("con=sqlite3.connect(r\"{}\")\n", db_path.replace('"',"\\\"")));
        py.push_str("cur=con.cursor()\n");
        py.push_str("cur.execute('''CREATE TABLE IF NOT EXISTS oha (url TEXT NOT NULL,start REAL NOT NULL,start_latency_correction REAL,end REAL NOT NULL,duration REAL NOT NULL,status INTEGER NOT NULL,len_bytes INTEGER NOT NULL,run INTEGER NOT NULL)''')\n");
        for v in insert_vals {
            py.push_str(&format!("cur.execute('INSERT INTO oha VALUES {}')\n", v));
        }
        py.push_str("con.commit()\ncon.close()\n");
        let _ = std::process::Command::new("python3").arg("-c").arg(py).status();
        out_str.push_str(&format!("\nStoring results to {}\n", db_path));
    }

    if let Some(out_path) = output_path {
        if let Err(e) = std::fs::write(&out_path, out_str.as_bytes()) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else {
        print!("{}", out_str);
    }
}

