        let dns_fast = dns_lookup_vals.first().cloned().unwrap_or(f64::NAN);
        let dns_slow = dns_lookup_vals.last().cloned().unwrap_or(f64::NAN);
        let mut dns_dialup_vals: Vec<f64> = results_vec.iter().filter_map(|r| r.dns_dialup).collect();
        dns_dialup_vals.sort_by(|a,b| a.partial_cmp(b).unwrap());
