                let min = succ_durs[0];
                let max = succ_durs[succ_durs.len()-1];
                let step = if max>min { (max-min)/10.0 } else { 0.0 };
                for i in 0..=10 { succ_hist.insert(format!("{}", if step==0.0 { min } else { min+step*i as f64 }),0); }
                for d in &succ_durs {
                    if step==0.0 {
                        if let Some(k)=succ_hist.keys().next().cloned() { *succ_hist.get_mut(&k).unwrap()+=1; }
                    } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k)=succ_hist.keys().nth(idx).cloned() { *succ_hist.get_mut(&k).unwrap()+=1; }
                    }
                }
