                    } else {
                        let idx = ((d-min)/step).floor() as usize;
                        let idx = std::cmp::min(idx,10);
                        if let Some(k)=fail_hist.keys().nth(idx).cloned() { *fail_hist.get_mut(&k).unwrap()+=1; }
                    }
                }
            } else { fail_hist.insert("NaN".to_string(),0); }

            let mut succ_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
            let mut fail_lp: BTreeMap<String, Option<f64>> = BTreeMap::new();
