fn parse_n_requests(s: &str) -> Result<u64, String> {
    if s.is_empty() { return Err("invalid digit found in string".to_string()); }
    let lower = s.to_lowercase();
    let (num_part, mult) = if lower.ends_with('k') { (&s[..s.len()-1], 1000) } else if lower.ends_with('m') { (&s[..s.len()-1], 1_000_000) } else { (s,1) };
    if num_part.is_empty() { return Err("invalid digit found in string".to_string()); }
    match num_part.parse::<u64>() {
        Ok(v) => Ok(v*mult),
        Err(_) => Err("invalid digit found in string".to_string()),
    }
}

fn parse_duration(s: &str) -> Result<Duration, String> {
    let s = s.trim();
    if s.is_empty() { return Err("expected number at 0".to_string()); }
    let mut num_end=0;
    let mut has_digit=false;
    let mut has_dot=false;
    for (i,c) in s.char_indices() {
        if c.is_ascii_digit() { has_digit=true; num_end=i+c.len_utf8(); }
        else if c=='.' { if has_dot { break; } has_dot=true; num_end=i+c.len_utf8(); }
        else { break; }
    }
    if !has_digit || num_end==0 { return Err("expected number at 0".to_string()); }
    let num_str=&s[..num_end];
    let unit_str=s[num_end..].trim();
    if unit_str.is_empty() { return Err("time unit needed, for example 10sec or 10ms".to_string()); }
    let num: f64 = num_str.parse().map_err(|_| "expected number at 0".to_string())?;
    let mult = match unit_str {
        "ns" => 1e-9,
        "us" | "µs" | "μs" => 1e-6,
        "ms" => 1e-3,
        "s" | "sec" | "secs" | "second" | "seconds" => 1.0,
        "m" | "min" | "mins" | "minute" | "minutes" => 60.0,
        "h" | "hour" | "hours" => 3600.0,
        "d" | "day" | "days" => 86400.0,
        "w" | "week" | "weeks" => 604800.0,
        _ => return Err(format!("unknown time unit \"{}\", supported units: ns, us/µs, ms, sec, min, hours, days, weeks, months, years (and few variations)", unit_str)),
    };
    Ok(Duration::from_secs_f64(num*mult))
}

fn generate_rand_url(pattern: &str, max_repeat: usize) -> String {
    use rand::Rng;
    let mut rng = rand::thread_rng();
    let mut out = String::new();
    let chars: Vec<char> = pattern.chars().collect();
    let mut i=0;
    while i<chars.len() {
        let c=chars[i];
        if c=='[' {
            let mut j=i+1;
            while j<chars.len() && chars[j]!=']' { j+=1; }
            if j>=chars.len() { out.push(c); i+=1; continue; }
            let inner: String = chars[i+1..j].iter().collect();
            let mut cand: Vec<char>=Vec::new();
            let ic: Vec<char>=inner.chars().collect();
            let mut k=0;
            while k<ic.len() {
                let ch=ic[k];
                if k+2<ic.len() && ic[k+1]=='-' {
                    let s=ch; let e=ic[k+2];
                    if s<=e { for rc in (s as u8)..=(e as u8) { cand.push(rc as char); } }
                    k+=3;
                } else { cand.push(ch); k+=1; }
            }
            if cand.is_empty() { cand.push('a'); }
            let mut repeat=1;
            let mut quant=' ';
            if j+1<chars.len() {
                let n=chars[j+1];
                if n=='*' || n=='+' || n=='?' { quant=n; }
                else if n=='{' {
                    let mut eb=j+2;
                    while eb<chars.len() && chars[eb]!='}' { eb+=1; }
                    if eb<chars.len() {
                        let bc: String = chars[j+2..eb].iter().collect();
                        if let Ok(nn)=bc.split(',').next().unwrap_or("1").trim().parse::<usize>() { repeat=nn; }
                        j=eb;
                    }
                }
            }
            if quant=='*' { repeat=rng.gen_range(0..=max_repeat); j+=1; }
            else if quant=='+' { repeat=1+rng.gen_range(0..=max_repeat); j+=1; }
            else if quant=='?' { repeat=if rng.gen_bool(0.5){1}else{0}; j+=1; }
            for _ in 0..repeat {
                let idx=rng.gen_range(0..cand.len());
                out.push(cand[idx]);
            }
            i=j+1;
        } else {
            out.push(c);
            i+=1;
        }
    }
    out
}

fn do_debug_request(matches: &clap::ArgMatches, url_str: &str, out_buf: &mut Vec<u8>, connect_timeout: Duration, timeout_opt: Option<Duration>) -> Result<(), String> {
    let parsed = match url::Url::parse(url_str) {
        Ok(u) => u,
        Err(_) => return Err(format!("relative URL without a base")),
    };
    let host = parsed.host_str().ok_or("no host")?.to_string();
    let port = parsed.port_or_known_default().unwrap_or(80);
    let path = if parsed.path().is_empty() { "/" } else { parsed.path() };
    let query = if let Some(q) = parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };
    let method = matches.get_one::<String>("method").map(|s| s.as_str()).unwrap_or("GET");
    let mut headers_vec: Vec<(String,String)> = Vec::new();
    if let Some(hs) = matches.get_many::<String>("headers") {
        for h in hs {
            if let Some((k,v)) = h.split_once(':') {
                headers_vec.push((k.trim().to_string(), v.trim().to_string()));
            }
        }
    }
    if let Some(a) = matches.get_one::<String>("accept") {
        headers_vec.push(("accept".to_string(), a.clone()));
    }
    if let Some(ct) = matches.get_one::<String>("content-type") {
        headers_vec.push(("content-type".to_string(), ct.clone()));
    }
    if let Some(h) = matches.get_one::<String>("host") {
        headers_vec.push(("host".to_string(), h.clone()));
    } else {
        headers_vec.push(("host".to_string(), format!("{}:{}", host, port)));
    }
    if let Some(auth) = matches.get_one::<String>("basic-auth") {
        let encoded = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
        headers_vec.push(("authorization".to_string(), format!("Basic {}", encoded)));
    }
    let mut body: Option<Vec<u8>> = None;
    if let Some(b) = matches.get_one::<String>("body-string") {
        body = Some(b.clone().into_bytes());
    } else if let Some(p) = matches.get_one::<String>("body-path") {
        match std::fs::read(p) {
            Ok(b) => body = Some(b),
            Err(e) => return Err(format!("{}", e)),
        }
    } else if let Some(p) = matches.get_one::<String>("body-lines") {
        match std::fs::read_to_string(p) {
            Ok(content) => {
                let lines: Vec<&str> = content.lines().collect();
                if !lines.is_empty() {
                    let mut rng = rand::thread_rng();
                    let idx = rng.gen_range(0..lines.len());
                    body = Some(lines[idx].as_bytes().to_vec());
                }
            },
            Err(e) => return Err(format!("{}", e)),
        }
    }
    let is_form = matches.contains_id("form");
    let mut boundary = String::new();
    if is_form {
        let mut rng = rand::thread_rng();
        let mut rand_bytes = [0u8;16];
        for i in 0..16 { rand_bytes[i]=rng.gen(); }
        let hex: String = rand_bytes.iter().map(|b| format!("{:02x}", b)).collect();
        boundary = format!("----formdata-oha-{}", hex);
        headers_vec.retain(|(k,_)| k.to_lowercase()!="content-type");
        headers_vec.push(("content-type".to_string(), format!("multipart/form-data; boundary={}", boundary)));
        let mut form_body: Vec<u8> = Vec::new();
        if let Some(forms) = matches.get_many::<String>("form") {
            for f in forms {
                if let Some((k,v)) = f.split_once('=') {
                    if v.starts_with('@') {
                        let path = &v[1..];
                        match std::fs::read(path) {
                            Ok(file_content) => {
                                let filename = std::path::Path::new(path).file_name().and_then(|s| s.to_str()).unwrap_or("file");
                                form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n", boundary, k, filename).as_bytes());
                                form_body.extend_from_slice(&file_content);
                                form_body.extend_from_slice(b"\r\n");
                            },
                            Err(e) => return Err(format!("{}", e)),
                        }
                    } else {
                        form_body.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, k, v).as_bytes());
                    }
                }
            }
        }
        form_body.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
        body = Some(form_body);
    }
    let method_for_debug = if is_form && method=="GET" { "POST" } else { method };
    let http_version_arg = matches.get_one::<String>("http-version").map(|s| s.as_str()).unwrap_or("1.1");
    let use_http2 = matches.get_flag("http2") || http_version_arg=="2";
    let uri_display = if use_http2 { url_str.to_string() } else { query.clone() };
    let version_display = if use_http2 { "HTTP/2.0" } else if http_version_arg=="1.0" { "HTTP/1.0" } else if http_version_arg=="0.9" { "HTTP/0.9" } else { "HTTP/1.1" };
    let disable_compression = matches.get_flag("disable-compression");
    let mut display_headers: BTreeMap<String,String> = BTreeMap::new();
    let mut has_accept=false; let mut has_ua=false;
    for (k,_) in &headers_vec {
        if k.to_lowercase()=="accept" { has_accept=true; }
        if k.to_lowercase()=="user-agent" { has_ua=true; }
    }
    if !has_accept { display_headers.insert("accept".to_string(), "*/*".to_string()); }
    if !disable_compression {
        if !display_headers.contains_key("accept-encoding") && !headers_vec.iter().any(|(k,_)| k.to_lowercase()=="accept-encoding") {
            display_headers.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string());
        }
    }
    if !has_ua { display_headers.insert("user-agent".to_string(), "oha/1.12.1".to_string()); }
    for (k,v) in headers_vec.iter() { display_headers.insert(k.to_lowercase(), v.clone()); }
    {
        use std::io::Write;
        writeln!(out_buf, "Request {{").unwrap();
        writeln!(out_buf, "    method: {},", method_for_debug).unwrap();
        writeln!(out_buf, "    uri: {},", uri_display).unwrap();
        writeln!(out_buf, "    version: {},", version_display).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &display_headers { writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap(); }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "    body: Full {{").unwrap();
        if let Some(b) = &body {
            let s = String::from_utf8_lossy(b);
            let esc = s.replace('\\',"\\\\").replace('"',"\\\"").replace('\n',"\\n").replace('\r',"\\r");
            writeln!(out_buf, "        data: Some(").unwrap();
            writeln!(out_buf, "            b\"{}\",", esc).unwrap();
            writeln!(out_buf, "        ),").unwrap();
        } else {
            writeln!(out_buf, "        data: None,").unwrap();
        }
        writeln!(out_buf, "    }},").unwrap();
        writeln!(out_buf, "}}").unwrap();
    }
    if use_http2 && parsed.scheme()!="https" { return Err("http2 error".to_string()); }
    if http_version_arg=="0.9" { return Err("dispatch task is gone".to_string()); }
    use std::net::{TcpStream, ToSocketAddrs};
    use std::io::{Read, Write};
    let mut target_host = host.clone();
    let mut target_port = port;
    if let Some(connect_tos) = matches.get_many::<String>("connect-to") {
        for ct in connect_tos {
            let parts: Vec<&str> = ct.split(':').collect();
            if parts.len()==4 {
                let orig_host=parts[0];
                let orig_port=parts[1].parse::<u16>().unwrap_or(0);
                let tgt_host=parts[2];
                let tgt_port=parts[3].parse::<u16>().unwrap_or(0);
                if orig_host==host && orig_port==port {
                    target_host=tgt_host.to_string();
                    target_port=tgt_port;
                }
            }
        }
    }
    let addr_str = format!("{}:{}", target_host, target_port);
    let mut stream_opt: Option<TcpStream> = None;
    let mut last_err=String::new();
    for addr in addr_str.to_socket_addrs().map_err(|e| format!("{}", e))? {
        match TcpStream::connect_timeout(&addr, connect_timeout) {
            Ok(s) => { stream_opt=Some(s); break; },
            Err(e) => { last_err=format!("{}", e); }
        }
    }
    let mut stream = match stream_opt { Some(s)=>s, None=>return Err(last_err) };
    if let Some(to)=timeout_opt {
        stream.set_read_timeout(Some(to)).ok();
        stream.set_write_timeout(Some(to)).ok();
    }
    let mut req_str = format!("{} {} {}\r\n", method_for_debug, query, version_display);
    for (k,v) in &display_headers { req_str.push_str(&format!("{}: {}\r\n", k, v)); }
    if let Some(b)=&body { req_str.push_str(&format!("content-length: {}\r\n", b.len())); }
    req_str.push_str("\r\n");
    if let Err(e)=stream.write_all(req_str.as_bytes()) { return Err(format!("{}", e)); }
    if let Some(b)=&body { if let Err(e)=stream.write_all(b) { return Err(format!("{}", e)); } }
    let mut resp_buf=Vec::new();
    let mut tmp=[0u8;4096];
    loop {
        match stream.read(&mut tmp) {
            Ok(0)=>break,
            Ok(n)=>resp_buf.extend_from_slice(&tmp[..n]),
            Err(e)=>{ if e.kind()==std::io::ErrorKind::TimedOut || e.kind()==std::io::ErrorKind::WouldBlock { return Err("timeout".to_string()); } return Err(format!("{}", e)); }
        }
    }
    let resp_str=String::from_utf8_lossy(&resp_buf);
    let mut lines=resp_str.lines();
    let status_line=lines.next().unwrap_or("");
    let mut status_code=200;
    let mut version_resp="HTTP/1.1";
    if status_line.starts_with("HTTP/") {
        let parts: Vec<&str>=status_line.split_whitespace().collect();
        if parts.len()>=2 {
            version_resp=parts[0];
            status_code=parts[1].parse().unwrap_or(200);
        }
    }
    let mut resp_headers: BTreeMap<String,String>=BTreeMap::new();
    let mut body_start=0;
    if let Some(pos)=resp_str.find("\r\n\r\n") {
        body_start=pos+4;
        let hp=&resp_str[..pos];
        for (i,line) in hp.split("\r\n").enumerate() {
            if i==0 { continue; }
            if let Some((k,v))=line.split_once(':') { resp_headers.insert(k.trim().to_lowercase(), v.trim().to_string()); }
        }
    }
    let body_bytes=if body_start < resp_buf.len() { &resp_buf[body_start..] } else { b"" };
    {
        use std::io::Write;
        writeln!(out_buf, "\nResponse {{").unwrap();
        writeln!(out_buf, "    status: {},", status_code).unwrap();
        writeln!(out_buf, "    version: {},", version_resp).unwrap();
        writeln!(out_buf, "    headers: {{").unwrap();
        for (k,v) in &resp_headers { writeln!(out_buf, "        \"{}\": \"{}\",", k, v).unwrap(); }
        writeln!(out_buf, "    }},").unwrap();
        let bs=String::from_utf8_lossy(body_bytes);
        let esc=bs.replace('\\',"\\\\").replace('"',"\\\"").replace('\n',"\\n").replace('\r',"\\r");
        writeln!(out_buf, "    body: b\"{}\",", esc).unwrap();
        writeln!(out_buf, "}}").unwrap();
    }
    Ok(())
}

fn do_single_request(
    url_str: &str,
    method: &str,
    headers_raw: &[String],
    connect_to_raw: &[String],
    host_override: Option<&str>,
    basic_auth: Option<&str>,
    accept_header: Option<&str>,
    content_type: Option<&str>,
    body_string: Option<&str>,
    body_from_file: Option<&[u8]>,
    body_lines: Option<&[Vec<u8>]>,
    forms: &[String],
    disable_keepalive: bool,
    disable_compression: bool,
    redirect_limit: usize,
    timeout_opt: Option<Duration>,
    connect_timeout: Duration,
    kept_stream: &mut Option<std::net::TcpStream>,
    kept_host: &mut String,
    kept_port: &mut u16,
) -> Result<(u16, usize, Option<f64>, Option<f64>, f64), (String, Option<f64>, Option<f64>)> {
    let mut cur_url = url_str.to_string();
    let mut cur_parsed = match url::Url::parse(&cur_url) { Ok(u)=>u, Err(_)=> return Err(("relative URL without a base".to_string(),None,None)) };
    let mut redirects=0;
    loop {
        let host = cur_parsed.host_str().unwrap_or("").to_string();
        let port = cur_parsed.port_or_known_default().unwrap_or(80);
        let path = if cur_parsed.path().is_empty() { "/" } else { cur_parsed.path() };
        let query = if let Some(q)=cur_parsed.query() { format!("{}?{}", path, q) } else { path.to_string() };
        let dns_start=Instant::now();
        use std::net::ToSocketAddrs;
        let addr_str=format!("{}:{}", host, port);
        let dns_lookup;
        let addrs: Vec<std::net::SocketAddr> = match addr_str.to_socket_addrs() {
            Ok(it)=>{ dns_lookup=dns_start.elapsed().as_secs_f64(); it.collect() },
            Err(e)=>{ return Err((format!("{}", e), Some(dns_start.elapsed().as_secs_f64()), None)); }
        };
        let dial_start=Instant::now();
        let mut stream_opt=None;
        let mut last_err=String::new();
        for addr in &addrs {
            match std::net::TcpStream::connect_timeout(addr, connect_timeout) {
                Ok(s)=>{ stream_opt=Some(s); break; },
                Err(e)=>{ last_err=format!("{}", e); }
            }
        }
        let mut stream = match stream_opt { Some(s)=>s, None=> return Err((last_err, Some(dns_lookup), None)) };
        let dns_dialup = dial_start.elapsed().as_secs_f64() + dns_lookup;
        let resp_delay_start = Instant::now();
        if let Some(to)=timeout_opt { stream.set_read_timeout(Some(to)).ok(); stream.set_write_timeout(Some(to)).ok(); }
        let mut disp: BTreeMap<String,String>=BTreeMap::new();
        if let Some(a)=accept_header { disp.insert("accept".to_string(), a.to_string()); } else { disp.insert("accept".to_string(), "*/*".to_string()); }
        if !disable_compression { disp.insert("accept-encoding".to_string(), "gzip, compress, deflate, br".to_string()); }
        disp.insert("user-agent".to_string(), "oha/1.12.1".to_string());
        if let Some(h)=host_override { disp.insert("host".to_string(), h.to_string()); } else { disp.insert("host".to_string(), format!("{}:{}", host, port)); }
        for h in headers_raw {
            if let Some((k,v))=h.split_once(':') { disp.insert(k.trim().to_lowercase(), v.trim().to_string()); }
        }
        if let Some(auth)=basic_auth {
            let enc = base64::Engine::encode(&base64::engine::general_purpose::STANDARD, auth.as_bytes());
            disp.insert("authorization".to_string(), format!("Basic {}", enc));
        }
        if let Some(ct)=content_type { disp.insert("content-type".to_string(), ct.to_string()); }
        let mut body_bytes: Option<Vec<u8>>=None;
        if let Some(s)=body_string { body_bytes=Some(s.as_bytes().to_vec()); }
        else if let Some(b)=body_from_file { body_bytes=Some(b.to_vec()); }
        else if let Some(lines)=body_lines {
            if !lines.is_empty() {
                let mut rng=rand::thread_rng();
                let idx=rng.gen_range(0..lines.len());
                body_bytes=Some(lines[idx].clone());
            }
        } else if !forms.is_empty() {
            let mut rng=rand::thread_rng();
            let mut rb=[0u8;16];
            for i in 0..16 { rb[i]=rng.gen(); }
            let hex: String = rb.iter().map(|b| format!("{:02x}", b)).collect();
            let boundary=format!("----formdata-oha-{}", hex);
            disp.insert("content-type".to_string(), format!("multipart/form-data; boundary={}", boundary));
            let mut fb: Vec<u8>=Vec::new();
            for f in forms {
                if let Some((k,v))=f.split_once('=') {
                    if v.starts_with('@') {
                        let p=&v[1..];
                        if let Ok(fc)=std::fs::read(p) {
                            let fnm=std::path::Path::new(p).file_name().and_then(|s| s.to_str()).unwrap_or("file");
                            fb.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"; filename=\"{}\"\r\n\r\n", boundary, k, fnm).as_bytes());
                            fb.extend_from_slice(&fc);
                            fb.extend_from_slice(b"\r\n");
                        }
                    } else {
                        fb.extend_from_slice(format!("--{}\r\nContent-Disposition: form-data; name=\"{}\"\r\n\r\n{}\r\n", boundary, k, v).as_bytes());
                    }
                }
            }
            fb.extend_from_slice(format!("--{}--\r\n", boundary).as_bytes());
            body_bytes=Some(fb);
        }
        let meth = if !forms.is_empty() && method=="GET" { "POST" } else { method };
        let mut req_str=format!("{} {} HTTP/1.1\r\n", meth, query);
        for (k,v) in &disp { req_str.push_str(&format!("{}: {}\r\n", k, v)); }
        if let Some(b)=&body_bytes { req_str.push_str(&format!("content-length: {}\r\n", b.len())); }
        req_str.push_str("\r\n");
        use std::io::{Read, Write};
        if let Err(e)=stream.write_all(req_str.as_bytes()) { return Err((format!("{}", e), Some(dns_lookup), Some(dns_dialup))); }
        if let Some(b)=&body_bytes { if let Err(e)=stream.write_all(b) { return Err((format!("{}", e), Some(dns_lookup), Some(dns_dialup))); } }
        let mut resp_buf=Vec::new();
        let mut tmp=[0u8;4096];
        let mut resp_delay=0.0;
        let mut first=true;
        loop {
            match stream.read(&mut tmp) {
                Ok(0)=>break,
                Ok(n)=>{
                    if first { resp_delay=resp_delay_start.elapsed().as_secs_f64(); first=false; }
                    resp_buf.extend_from_slice(&tmp[..n]);
                    if let Some(pos)=resp_buf.windows(4).position(|w| w==b"\r\n\r\n") {
                        let hstr=String::from_utf8_lossy(&resp_buf[..pos]);
                        let mut cl: Option<usize>=None;
                        for line in hstr.lines().skip(1) {
                            if let Some((k,v))=line.split_once(':') {
                                if k.trim().to_lowercase()=="content-length" { cl=v.trim().parse().ok(); }
                            }
                        }
                        if let Some(l)=cl { if resp_buf.len()>=pos+4+l { break; } }
                    }
                },
                Err(e)=>{
                    if e.kind()==std::io::ErrorKind::TimedOut || e.kind()==std::io::ErrorKind::WouldBlock {
                        return Err((format!("timeout"), Some(dns_lookup), Some(dns_dialup)));
                    }
                    return Err((format!("{}", e), Some(dns_lookup), Some(dns_dialup)));
                }
            }
        }
        let resp_str=String::from_utf8_lossy(&resp_buf);
        let mut status=200;
        let mut loc: Option<String>=None;
        let mut lines=resp_str.lines();
        if let Some(sl)=lines.next() {
            if sl.starts_with("HTTP/") {
                let parts: Vec<&str>=sl.split_whitespace().collect();
                if parts.len()>=2 { status=parts[1].parse().unwrap_or(200); }
            }
        }
        for line in resp_str.split("\r\n").skip(1) {
            if line.is_empty() { break; }
            if let Some((k,v))=line.split_once(':') {
                if k.trim().to_lowercase()=="location" { loc=Some(v.trim().to_string()); }
            }
        }
        if status>=300 && status<400 && redirect_limit>0 {
            if let Some(l)=loc {
                if redirects < redirect_limit {
                    let next = match url::Url::parse(&l) {
                        Ok(u)=>u.to_string(),
                        Err(_) => {
                            if let Ok(base)=url::Url::parse(&cur_url) {
                                if let Ok(joined)=base.join(&l) { joined.to_string() } else { l.clone() }
                            } else { l.clone() }
                        }
                    };
                    cur_url=next;
                    cur_parsed=match url::Url::parse(&cur_url) { Ok(u)=>u, Err(_)=>cur_parsed.clone() };
                    redirects+=1;
                    continue;
                } else {
                    return Err((format!("Redirection limit has reached"), Some(dns_lookup), Some(dns_dialup)));
                }
            }
        }
        let body_start = if let Some(pos)=resp_buf.windows(4).position(|w| w==b"\r\n\r\n") { pos+4 } else { resp_buf.len() };
        let body_len = resp_buf.len() - body_start;
        if !disable_keepalive {
            if kept_host.is_empty() || *kept_host==host && *kept_port==port {
                *kept_stream=Some(stream);
                *kept_host=host;
                *kept_port=port;
            }
        }
        return Ok((status as u16, body_len, Some(dns_lookup), Some(dns_dialup), resp_delay));
    }
}

fn convert_time(secs: f64, unit: &str) -> f64 {
    match unit {
        "ns" => secs*1e9,
        "us" => secs*1e6,
        "ms" => secs*1e3,
        "s" => secs,
        "m" => secs/60.0,
        "h" => secs/3600.0,
        _ => secs,
    }
}

fn format_time(secs: f64, unit: &str) -> String {
    if secs.is_nan() { return format!("NaN {}", unit); }
    if secs.is_infinite() { if secs.is_sign_negative() { return format!("-inf {}", unit); } else { return format!("inf {}", unit); } }
    format!("{:.4} {}", convert_time(secs, unit), unit)
}

fn format_time_auto(secs: f64) -> String {
    if secs.is_nan() { return "NaN ns".to_string(); }
    if secs.is_infinite() { if secs.is_sign_negative() { return "-inf ns".to_string(); } else { return "inf ns".to_string(); } }
    if secs < 0.000001 { format!("{:.4} ns", secs*1e9) }
    else if secs < 0.001 { format!("{:.4} us", secs*1e6) }
    else if secs < 1.0 { format!("{:.4} ms", secs*1e3) }
    else { format!("{:.4} sec", secs) }
}

fn format_data_rate(bps: f64) -> String {
    if bps < 1024.0 { format!("{} B", bps as usize) }
    else if bps < 1024.0*1024.0 { format!("{:.2} KiB", bps/1024.0) }
    else { format!("{:.2} MiB", bps/(1024.0*1024.0)) }
}
