        let mut py = String::new();
        py.push_str("import sqlite3\\n");
        py.push_str(&format!("con=sqlite3.connect(r\\"{}\\")\\n", db_path.replace('"',"\\\"")));
        py.push_str("cur=con.cursor()\\n");
        py.push_str("cur.execute('''CREATE TABLE IF NOT EXISTS oha (url TEXT NOT NULL,start REAL NOT NULL,start_latency_correction REAL,end REAL NOT NULL,duration REAL NOT NULL,status INTEGER NOT NULL,len_bytes INTEGER NOT NULL,run INTEGER NOT NULL)''')\\n");
        for v in insert_vals {
            py.push_str(&format!("cur.execute('INSERT INTO oha VALUES {}')\\n", v));
        }
        py.push_str("con.commit()\\ncon.close()\\n");
        let _ = std::process::Command::new("python3").arg("-c").arg(py).status();
        out_str.push_str(&format!("\\nStoring results to {}\\n", db_path));
    }

    if let Some(out_path) = output_path {
        if let Err(e) = std::fs::write(&out_path, out_str.as_bytes()) {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    } else {
        print!("{}", out_str);
    }
}

